window.location.href=&quot;...&quot;;
创建标签
//创建表格及表头var table=document.createElement(&quot;table&quot;);var thead=document.createElement(&quot;thead&quot;);var tr_arr=[&quot;名字&quot;,&quot;作者&quot;,&quot;语言&quot;];for(var i=0;i&lt;3;i++)&#123;    var tr=document.createElement(&quot;tr&quot;);    tr.innerHTML=tr_arr[i];    thead.appendChild(tr);&#125;table.appendChild(thead);var container=document.getElementById(&quot;container&quot;);container.appendChild(table);console.log(container);
给元素加上class属性
// 假设你想给一个id为&quot;myElement&quot;的元素添加一个class &quot;new-class&quot;var element = document.getElementById(&quot;myElement&quot;);element.classList.add(&quot;new-class&quot;);
