$primary: #3490dc;$radius: 12px;.button &#123;  background: $primary;  border-radius: $radius;&#125;
Mixin（样式片段）
@mixin center &#123;  display: flex;  justify-content: center;  align-items: center;&#125;.box &#123;  @include center;&#125;
