nextTick
getHotItems(newVal, current_category)  .then((res: any) =&gt; &#123;    setUpNewsList(res);  &#125;)  .finally(async () =&gt; &#123;    await nextTick(); // ⭐ 关键：等 Skeleton 先被渲染一帧    loading.value = false;  &#125;)  .catch(console.error);
类型断言
const newsList = ref&lt;NewsItem[]&gt;(  new Array(10)    .fill(null as unknown as NewsItem)    .map(() =&gt; (&#123; ...tempNewsItem &#125;)));
as unknown 先隐藏，然后再断言为 NewsItem
小括号包大括号
new Array(10)  .fill(null as unknown as NewsItem)  .map(() =&gt; (&#123; ...tempNewsItem &#125;));
这样才有 return 的含义

树节点
select T1.id,    case        when T1.p_id is null then &quot;Root&quot;        when not exists            (                select *                from Tree T2                where T1.id = T2.p_id            )        then &quot;Leaf&quot;        else &quot;Inner&quot;    end as typefrom Tree T1;
2016 年的投资
# Write your MySQL query statement belowselect round(sum(I1.tiv_2016), 2) as tiv_2016from Insurance I1where    exists    (        select *        from Insurance I2        where I1.pid != I2.pid and I1.tiv_2015 = I2.tiv_2015    )    and    not exists    (        select *        from Insurance I2        where I1.pid != I2.pid and I1.lat = I2.lat and I1.lon = I2.lon    );
count 是行数, sum 是总和
游戏玩法分析 IV
select    round(        count(distinct T.player_id) / (select count(distinct Activity.player_id) from Activity), 2    ) as fractionfrom (    select Activity.player_id, min(event_date) as first_day    from Activity    group by player_id) T join Activity A on T.player_id = A.player_id and datediff(A.event_date, T.first_day) = 1;
这个 T 可能也可以指代 join 之后的表, 就是不是从全表搜索的, 有点乱,
我也不太懂, 但是这能过
select    round(        count(distinct T2.player_id) / (select count(distinct Activity.player_id) from Activity), 2    ) as fractionfrom (    select T.player_id    from (        select Activity.player_id, min(event_date) as first_day        from Activity        group by player_id    ) T    join    Activity A    on T.player_id = A.player_id and datediff(A.event_date, T.first_day) = 1) T2;
这个可能是比较好懂的, 但是性能差了一点, 注意 join
之后的表不能直接起别名, 所以这里加了一个 select 语句把这个 join
包起来

Map 基本用法
var m = new Map(); // 空Mapm.set(&quot;Adam&quot;, 67); // 添加新的key-valuem.set(&quot;Bob&quot;, 59);m.has(&quot;Adam&quot;); // 是否存在key &#x27;Adam&#x27;: truem.get(&quot;Adam&quot;); // 67m.delete(&quot;Adam&quot;); // 删除key &#x27;Adam&#x27;m.get(&quot;Adam&quot;); // undefined
事件发射器
class EventEmitter &#123;  mp = new Map(); // class里面不能带const或者let  /**   * @param &#123;string&#125; eventName   * @param &#123;Function&#125; callback   * @return &#123;Object&#125;   */  subscribe(eventName, callback) &#123;    if (!this.mp.has(eventName)) &#123;      this.mp.set(eventName, [callback]);    &#125; else &#123;      this.mp.set(eventName, [...this.mp.get(eventName), callback]);    &#125;    return &#123;      unsubscribe: () =&gt; &#123;        this.mp.set(          eventName,          this.mp.get(eventName).filter((item) =&gt; &#123;            if (item == callback) &#123;              return false;            &#125;            return true;          &#125;)        );      &#125;,    &#125;;  &#125;  /**   * @param &#123;string&#125; eventName   * @param &#123;Array&#125; args   * @return &#123;Array&#125;   */  emit(eventName, args = []) &#123;    const funcs = this.mp.get(eventName) || []; // 注意这里可能funcs是空的, 所以或上[]    let res = [];    for (const func of funcs) &#123;      res.push(func(...args));    &#125;    return res;  &#125;&#125;/** * const emitter = new EventEmitter(); * * // Subscribe to the onClick event with onClickCallback * function onClickCallback() &#123; return 99 &#125; * const sub = emitter.subscribe(&#x27;onClick&#x27;, onClickCallback); * * emitter.emit(&#x27;onClick&#x27;); // [99] * sub.unsubscribe(); // undefined * emitter.emit(&#x27;onClick&#x27;); // [] */
splice 函数
splice(start, deleteCount, elem1, elem2, …, elemn) 开始的位置,
删除的元素个数, 在 start 这个位置插入 elem1, …, elemn 这 n 个元素
精简对象
/** * @param &#123;Object|Array&#125; obj * @return &#123;Object|Array&#125; */var compactObject = function (obj) &#123;  if (obj instanceof Array) &#123;    for (let i = 0; i &lt; obj.length; i++) &#123;      if (obj[i] instanceof Object) &#123;        obj[i] = compactObject(obj[i]);      &#125; else &#123;        if (Boolean(obj[i]) === false) &#123;          obj.splice(i, 1);          i--;        &#125;      &#125;    &#125;  &#125; else &#123;    for (const key in obj) &#123;      if (obj[key] instanceof Object) &#123;        // obj.key是不行的, key是字符串, 要通过索引去访问        obj[key] = compactObject(obj[key]);      &#125; else &#123;        if (Boolean(obj[key]) === false) &#123;          delete obj[key];        &#125;      &#125;    &#125;  &#125;  return obj;&#125;;
js 下标越界
下标越界的时候, 数组长度会自动变成下标+1
并行执行异步函数
/** * @param &#123;Array&lt;Function&gt;&#125; functions * @return &#123;Promise&lt;any&gt;&#125; */var promiseAll = function (functions) &#123;  return new Promise((resolve, reject) =&gt; &#123;    if (functions == []) &#123;      resolve([]);      return;    &#125;    let res = [];    let resolvedCount = 0;    functions.forEach(async (func, idx) =&gt; &#123;      try &#123;        res[idx] = await func();        if (++resolvedCount == functions.length) &#123;          resolve(res);        &#125;      &#125; catch (err) &#123;        reject(err);      &#125;    &#125;);  &#125;);&#125;;/** * const promise = promiseAll([() =&gt; new Promise(res =&gt; res(42))]) * promise.then(console.log); // [42] */
其实 functions == []这个语法是错误的, functions 是对象, 就算它值是[],
[] == []还是不一样的, 实际上比较的是引用, 应该用 functions.length == 0
来判断
/** * @param &#123;Array&lt;Function&gt;&#125; functions * @return &#123;Promise&lt;any&gt;&#125; */var promiseAll = function (functions) &#123;  return new Promise((resolve, reject) =&gt; &#123;    if (functions.length == 0) &#123;      resolve([]);      return;    &#125;    let res = [];    let resolvedCount = 0;    functions.forEach((func, idx) =&gt; &#123;      func()        .then((rest) =&gt; &#123;          res[idx] = rest;          if (++resolvedCount == functions.length) &#123;            resolve(res);          &#125;        &#125;)        .catch((err) =&gt; reject(err));    &#125;);  &#125;);&#125;;/** * const promise = promiseAll([() =&gt; new Promise(res =&gt; res(42))]) * promise.then(console.log); // [42] */
这是 then catch 的写法
根据 ID 合并两个数组
/** * @param &#123;Array&#125; arr1 * @param &#123;Array&#125; arr2 * @return &#123;Array&#125; */var join = function (arr1, arr2) &#123;  arr1.sort((i, j) =&gt; i[&quot;id&quot;] - j[&quot;id&quot;]);  arr2.sort((i, j) =&gt; i[&quot;id&quot;] - j[&quot;id&quot;]);  const arr = [];  let p1 = 0,    p2 = 0,    p = 0;  while (p1 &lt; arr1.length || p2 &lt; arr2.length) &#123;    if (p1 == arr1.length) &#123;      arr[p++] = arr2[p2++];      continue;    &#125;    if (p2 == arr2.length) &#123;      arr[p++] = arr1[p1++];      continue;    &#125;    if (arr1[p1][&quot;id&quot;] == arr2[p2][&quot;id&quot;]) &#123;      const new_obj = &#123;&#125;;      for (const key in arr2[p2]) &#123;        new_obj[key] = arr2[p2][key];      &#125;      for (const key in arr1[p1]) &#123;        if (!new_obj.hasOwnProperty(key)) &#123;          new_obj[key] = arr1[p1][key];        &#125;      &#125;      p1++;      p2++;      arr[p++] = new_obj;    &#125; else if (arr1[p1][&quot;id&quot;] &lt; arr2[p2][&quot;id&quot;]) &#123;      arr[p++] = arr1[p1++];    &#125; else &#123;      arr[p++] = arr2[p2++];    &#125;  &#125;  return arr;&#125;;
至此, 力扣 js 中等题里面除了要解锁的, 都被我刷完了
生成斐波那契数列
/** * @return &#123;Generator&lt;number&gt;&#125; */var fibGenerator = function* () &#123;  yield 0;  yield 1;  let a = 0,    b = 1;  for (let i = 3; ; i++) &#123;    yield a + b;    b = a + b;    a = b - a;  &#125;&#125;;/** * const gen = fibGenerator(); * gen.next().value; // 0 * gen.next().value; // 1 */
迭代的方法
/** * @return &#123;Generator&lt;number&gt;&#125; */var fibGenerator = function* (pre = 0, cur = 1) &#123;  yield pre;  yield* fibGenerator(cur, pre + cur);&#125;;/** * const gen = fibGenerator(); * gen.next().value; // 0 * gen.next().value; // 1 */
递归法
包装数组
/** * @param &#123;number[]&#125; nums * @return &#123;void&#125; */var ArrayWrapper = function (nums) &#123;  this.arr = [...nums];&#125;;/** * @return &#123;number&#125; */ArrayWrapper.prototype.valueOf = function () &#123;  let res = 0;  for (const item of this.arr) &#123;    res += item;  &#125;  return res;&#125;;/** * @return &#123;string&#125; */ArrayWrapper.prototype.toString = function () &#123;  return &quot;[&quot; + this.arr.toString() + &quot;]&quot;;&#125;;/** * const obj1 = new ArrayWrapper([1,2]); * const obj2 = new ArrayWrapper([3,4]); * obj1 + obj2; // 10 * String(obj1); // &quot;[1,2]&quot; * String(obj2); // &quot;[3,4]&quot; */
相等还是不相等
/** * @param &#123;string&#125; val * @return &#123;Object&#125; */var expect = function (val) &#123;  return &#123;    toBe(_val) &#123;      if (val === _val) &#123;        return true;      &#125;      throw new Error(&quot;Not Equal&quot;);    &#125;,    notToBe(_val) &#123;      if (val !== _val) &#123;        return true;      &#125;      throw new Error(&quot;Equal&quot;);    &#125;,  &#125;;&#125;;/** * expect(5).toBe(5); // true * expect(5).notToBe(5); // throws &quot;Equal&quot; */
执行可取消的延迟函数
/** * @param &#123;Function&#125; fn * @param &#123;Array&#125; args * @param &#123;number&#125; t * @return &#123;Function&#125; */var cancellable = function (fn, args, t) &#123;  let timer = setTimeout(() =&gt; &#123;    fn(...args);  &#125;, t);  return function () &#123;    clearTimeout(timer);  &#125;;&#125;;/** *  const result = []; * *  const fn = (x) =&gt; x * 5; *  const args = [2], t = 20, cancelTimeMs = 50; * *  const start = performance.now(); * *  const log = (...argsArr) =&gt; &#123; *      const diff = Math.floor(performance.now() - start); *      result.push(&#123;&quot;time&quot;: diff, &quot;returned&quot;: fn(...argsArr)&#125;); *  &#125; * *  const cancel = cancellable(log, args, t); * *  const maxT = Math.max(t, cancelTimeMs); * *  setTimeout(cancel, cancelTimeMs); * *  setTimeout(() =&gt; &#123; *      console.log(result); // [&#123;&quot;time&quot;:20,&quot;returned&quot;:10&#125;] *  &#125;, maxT + 15) */
间隔取消
/** * @param &#123;Function&#125; fn * @param &#123;Array&#125; args * @param &#123;number&#125; t * @return &#123;Function&#125; */var cancellable = function (fn, args, t) &#123;  fn(...args);  let timer = setInterval(() =&gt; &#123;    fn(...args);  &#125;, t);  return function () &#123;    clearInterval(timer);  &#125;;&#125;;/** *  const result = []; * *  const fn = (x) =&gt; x * 2; *  const args = [4], t = 35, cancelTimeMs = 190; * *  const start = performance.now(); * *  const log = (...argsArr) =&gt; &#123; *      const diff = Math.floor(performance.now() - start); *      result.push(&#123;&quot;time&quot;: diff, &quot;returned&quot;: fn(...argsArr)&#125;); *  &#125; * *  const cancel = cancellable(log, args, t); * *  setTimeout(cancel, cancelTimeMs); * *  setTimeout(() =&gt; &#123; *      console.log(result); // [ *                           //     &#123;&quot;time&quot;:0,&quot;returned&quot;:8&#125;, *                           //     &#123;&quot;time&quot;:35,&quot;returned&quot;:8&#125;, *                           //     &#123;&quot;time&quot;:70,&quot;returned&quot;:8&#125;, *                           //     &#123;&quot;time&quot;:105,&quot;returned&quot;:8&#125;, *                           //     &#123;&quot;time&quot;:140,&quot;returned&quot;:8&#125;, *                           //     &#123;&quot;time&quot;:175,&quot;returned&quot;:8&#125; *                           // ] *  &#125;, cancelTimeMs + t + 15) */
setInterval 在 0ms, 不会立即执行一次
使用方法链的计算器
class Calculator &#123;  /**   * @param &#123;number&#125; value   */  constructor(value) &#123;    this.result = value;    return this;  &#125;  /**   * @param &#123;number&#125; value   * @return &#123;Calculator&#125;   */  add(value) &#123;    this.result += value;    return this;  &#125;  /**   * @param &#123;number&#125; value   * @return &#123;Calculator&#125;   */  subtract(value) &#123;    this.result -= value;    return this;  &#125;  /**   * @param &#123;number&#125; value   * @return &#123;Calculator&#125;   */  multiply(value) &#123;    this.result *= value;    return this;  &#125;  /**   * @param &#123;number&#125; value   * @return &#123;Calculator&#125;   */  divide(value) &#123;    if (value == 0) &#123;      throw &quot;Division by zero is not allowed&quot;;    &#125;    this.result /= value;    return this;  &#125;  /**   * @param &#123;number&#125; value   * @return &#123;Calculator&#125;   */  power(value) &#123;    this.result **= value;    return this;  &#125;  /**   * @return &#123;number&#125;   */  getResult() &#123;    return this.result;  &#125;&#125;
Math.row(a, b)和 a ** b 都是能够计算次方的
判断对象是否为空
/** * @param &#123;Object|Array&#125; obj * @return &#123;boolean&#125; */var isEmpty = function (obj) &#123;  if (JSON.stringify(obj) == JSON.stringify(&#123;&#125;)) &#123;    return true;  &#125;  if (JSON.stringify(obj) == JSON.stringify([])) &#123;    return true;  &#125;  return false;&#125;;
判断两个对象是否相等的方法, 就是用 JSON.stringify()

Codeforces Round 1060 (Div. 2) C2 题意: 给定一个n, 还有长度为n的数组a和b, a是数字, b是代价, 每次可以修改一个a中的元素, 使其+1, 求使得数组当中存在gcd(a[i], a[j]) &gt; 1的最小代价 思路: 一开始呢, 我观察到了, 最小的代价不会超过b[i] + b[j], 因为如果我指定了a[i], a[j], 想要让他们的gcd &gt; 1, 我们分类讨论:
a[i] % 2 == 0 and a[j] % 2 == 0, 代价为0 a[i] % 2 == 1 and a[j] % 2 == 0, 代价为b[i] a[i] % 2 == 1 and a[j] % 2 == 1, 代价为b[i] + b[j]
从这里我们可以发现, 如果涉及到改两个元素的操作, 最多不超过2次, 剩下的操作就是选其中一个元素使其变成某个质因数的倍数 我一开始在想, 我对于每个a_i, 我去枚举质因数, 然后计算代价, 这样是超时的, 然后我又想着说, 反过来, 我枚举每个质因数, 然后再枚举质因数的倍数, 去找最接近这个倍数的a[i], 这样的时间复杂度, 不会超过max(a) * log(max(a)) ^ 2, 但是没想到还是超时了 最后看了题解, 它是这样说的, 我们把b从小到大排序, 观察到b[1] + b[x] &lt;= 2 * b[x], 所以选择其中一个元素, 最多也不会操作超过1次, 除了最小的那个, 所以我们只需要对于a[1]去计算到所有质因数的代价里面最小的那个就行了 代码: 这个是最开始的那一坨, 不过做了很多优化, 时间比较快 #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queue// suppose I want gcd(a[i], a[j]) &gt; 1, and I want to change both a[i] and a[j]// then a[i] and a[j] can be changed at most 1 times// if a[i] % 2 == 1 and a[j] % 2 == 1, then a[i]++, a[j]++// if a[i] % 2 == 0 and a[j] % 2 == 1, then a[j]++// if a[i] % 2 == 0 and a[j] % 2 == 0, we don&#x27;t have to do anything// beside these cases, other cases&#x27;s solution will be a[i] change k times to reach some a[j]&#x27;s prime factor// maybe I should do it backwards, for a fixed prime factor p, iterate it&#x27;s multiple and find the closest a[i]// also I figured out that for the same element in a, I should only care about the element with the lower cost// the biggest multiple should be 4e5, assume that we have two very big primes p1 and p2, and they are near 2e5// p1 &lt; p2, p2 want to have a prime factor p1, then we should find a k that makes k * p1 &gt;= p2, k &gt;= p2 / p1// fuck it&#x27;s kind of hard to prove that 4e5 is true, but I believe it&#x27;s true// after reading the editorial// if we want to make gcd(a[i], a[j]) &gt; 1, the cost is &lt;= b[i] + b[j]// let say we sort b, we claim that we only modify the a[i] with the smallest b[i]// if we choose to modify a[x] more than one time, the cost will be k * b[i] (k &gt;= 2)// but b[1] + b[x] &lt;= k * b[x]// so if we want to modify an element more than one time, then we choose element with the the lowest b[i]const int N = 2e5 + 5;int new_b[N], lm[N + N];bool vis[N];vector&lt;int&gt; primes, minp;void sieve(int n) &#123; minp.assign(n + 1, 0); for (int i = 2; i &lt;= n; i++) &#123; if (minp[i] == 0) &#123; primes.push_back(i); minp[i] = i; &#125; for (int p : primes) &#123; if (1LL * i * p &gt; n) break; minp[i * p] = p; if (minp[i] == p) break; &#125; &#125;&#125;void clear(const vt&lt;int&gt; &amp;S) &#123; for (int x : S) &#123; vis[x] = false; &#125;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5), b(n + 5); // unordered_map&lt;int, int&gt; vis; bool flag = false; vt&lt;int&gt; S; int mxa = 0; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; new_b[a[i]] = 1e9; mxa = max(mxa, a[i]); &#125; // for (int p : primes) &#123; // if (p &gt; mxa) &#123; // break; // &#125; // vis[p] = false; // &#125; for (int i = 1; i &lt;= n; i++) &#123; int t = a[i]; while (minp[t]) &#123; int p = minp[t]; if (vis[p]) &#123; flag = true; break; &#125; vis[p] = true; S.pb(p); while (t % p == 0) &#123; t /= p; &#125; &#125; if (flag) &#123; break; &#125; &#125; sort(all(S)); S.erase(unique(all(S)), S.end()); int mn_a = 1e9, mn_b = 1e9; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; b[i]; new_b[a[i]] = min(new_b[a[i]], b[i]); if (new_b[a[i]] &lt; mn_b) &#123; mn_b = min(mn_b, new_b[a[i]]); mn_a = a[i]; &#125; &#125; if (flag) &#123; clear(S); cout &lt;&lt; &quot;0
&quot;; return; &#125; ll ans = 1e18; for (int i = 1; i &lt;= n; i++) &#123; int t = a[i] + 1; while (minp[t]) &#123; // db(t), db(minp[t]), el; if (vis[minp[t]]) &#123; ans = min(ans, (ll)b[i]); &#125; t /= minp[t]; &#125; &#125; vt&lt;int&gt; odd_costs; for (int i = 1; i &lt;= n; i++) &#123; if (a[i] % 2) odd_costs.pb(b[i]); &#125; sort(all(odd_costs)); if (sz(odd_costs) &gt;= 2) &#123; ans = min(ans, 1LL * odd_costs[0] + odd_costs[1]); &#125; sort(rg(a, 1, n)); // db(ans), el; // n = unique(rg(a, 1, n)) - a.begin() - 1; // int ptr = 1; // for (int i = 1; i &lt;= mxa + mxa; i++) &#123; // while (ptr &lt;= n &amp;&amp; a[ptr] &lt; i) &#123; // ptr++; // &#125; // ptr--; // if (ptr &gt;= 1 &amp;&amp; a[ptr] &lt; i) &#123; // lm[i] = ptr; // &#125; else &#123; // lm[i] = 0; // &#125; // &#125; for (int p : S) &#123; if (mn_a % p == 0) continue; ans = min(ans, (1LL * p - mn_a % p) * mn_b); &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;; clear(S);&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); sieve(2e5); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queueconst int MN = 2e5;vt&lt;int&gt; pfac[MN + 5];void init() &#123; for (int i = 2; i &lt;= MN; i++) &#123; if (!pfac[i].empty()) continue; for (int j = i; j &lt;= MN; j += i) &#123; pfac[j].pb(i); &#125; &#125;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;ll&gt; a(n + 5), b(n + 5); set&lt;int&gt; all_p; bool flag = false; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; for (int p : pfac[a[i]]) &#123; if (all_p.count(p)) &#123; flag = true; &#125; all_p.insert(p); &#125; &#125; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; b[i]; &#125; if (flag) &#123; cout &lt;&lt; &quot;0
&quot;; return; &#125; ll ans = 1e18; for (int i = 1; i &lt;= n; i++) &#123; ll t = a[i] + 1; for (int p : pfac[t]) &#123; if (all_p.count(p)) &#123; ans = min(ans, b[i]); &#125; &#125; &#125; ll min_odd1 = 1e18, min_odd2 = 1e18; for (int i = 1; i &lt;= n; i++) &#123; if (a[i] % 2 == 0) continue; if (b[i] &lt;= min_odd1) &#123; min_odd2 = min_odd1; min_odd1 = b[i]; &#125; else if (b[i] &lt; min_odd2) &#123; min_odd2 = b[i]; &#125; &#125; ans = min(ans, min_odd1 + min_odd2); vt&lt;int&gt; ord(n + 5); iota(rg(ord, 1, n), 1); sort(rg(ord, 1, n), [&amp;](auto i, auto j) &#123; return b[i] &lt; b[j]; &#125;); for (int p : all_p) &#123; if (a[ord[1]] % p == 0) continue; ans = min(ans, (p - a[ord[1]] % p) * b[ord[1]]); &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); init(); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; Codeforces Round 1060 (Div. 2) D 题意: 给定一个n, 有一个数组a_1, …, a_2n, 里面的元素为[1, n], 并且每个数字都出现了两次, 可以询问一个子序列, 返回结果为MAD([a_j1, a_j2, …, a_jk]), MAD就是出现了两次的元素当中, 最大的那一个元素, 叫我用不超过3n次询问, 找到数组a长什么样子 思路: 我几乎没有思路, 我一直在想, 如果我只问两个坐标, 然后返回了非零的结果, 那我就能确定这两个坐标对应的值是什么了。题解十分地简洁，假定我们有一个集合S, ask(S)的结果是0, 那么如果ask(S U i)的结果非零, 我们则知道了a_i的值, 我们逐个加入下标i, 把数组划分为两个集合S1和S2, ask(S1) = 0, ask(S2) = 0, 在分割出S1的过程当中, 已经得到了n个位置的值, 就是S2对应下标的值, 然后我们再通过往S2添加S1的某个下标, 来得到S1对应下标的值, 总共的询问次数就是2n-1 + n = 3n-1 代码: #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queueint ask(const vt&lt;int&gt; &amp;arr) &#123; cout &lt;&lt; &quot;? &quot; &lt;&lt; sz(arr) &lt;&lt; &quot; &quot;; for (int x : arr) &#123; cout &lt;&lt; x &lt;&lt; &quot; &quot;; &#125; cout &lt;&lt; endl; int res; cin &gt;&gt; res; return res;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; S1 = &#123;1&#125;, S2; vt&lt;bool&gt; inS1(n + 5); inS1[1] = true; n *= 2; vt&lt;int&gt; a(n + 5); for (int i = 2; i &lt;= n; i++) &#123; S1.pb(i); int res = ask(S1); if (res) &#123; S1.pop_back(); S2.pb(i); a[i] = res; &#125; &#125; for (int x : S1) &#123; S2.pb(x); int res = ask(S2); S2.pop_back(); a[x] = res; &#125; cout &lt;&lt; &quot;! &quot;; for (int i = 1; i &lt;= n; i++) &#123; cout &lt;&lt; a[i] &lt;&lt; &quot; &quot;; &#125; cout &lt;&lt; endl;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;

Codeforces Round 1078 (Div. 2) D 题意: 一个n*m的01矩阵a, 要分成两部分, 只能画一条线分, 线的走向只能往右或者往下, 求分成两个矩阵后, 矩阵1包含1的个数为t1, 矩阵2包含1的个数为t2, 求t1*t2的最大值 思路: 很显然, t1*t2要最大, 那么t1和t2越接近越好, 我一开始的想法是看左下角, 把这个问题看成是每一行选几列的问题, 然后写了一个时间复杂度和空间复杂度都爆炸的dp, 后来又看了题解, 发现自己真的是傻逼, 只需要看右上角, 尽量地去拿就行了, 因为每次我拿的时候, 1的个数只会增加1, 而且右上角每次拿的数只会比上一行小, 这是可以控制的, 左下角就不具有这个性质, 我严重怀疑如果我不会dp, 我反而能在比赛当中做出这道题 代码(dp): #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int n, m; cin &gt;&gt; n &gt;&gt; m; vt&lt;vt&lt;ll&gt;&gt; a(n + 5, vt&lt;ll&gt;(m + 5)); vt&lt;vt&lt;ll&gt;&gt; pref(n + 5, vt&lt;ll&gt;(m + 5)); int tot = 0; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 1; j &lt;= m; j++) &#123; cin &gt;&gt; a[i][j]; if (a[i][j] == 1) &#123; tot++; &#125; pref[i][j] = pref[i][j - 1] + a[i][j]; &#125; &#125; int cnt = (tot + 1) / 2; vt&lt;vt&lt;vt&lt;bool&gt;&gt;&gt; dp(n + 5, vt&lt;vt&lt;bool&gt;&gt;(m + 5, vt&lt;bool&gt;(cnt + 5))); dp[0][0][0] = true; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 0; j &lt;= cnt; j++) &#123; for (int j1 = 0; j1 &lt;= m; j1++) &#123; for (int j2 = 0; j2 &lt;= j1; j2++) &#123; ll num1 = pref[i][j1]; if (j - num1 &gt;= 0) &#123; dp[i][j1][j] = dp[i][j1][j] || dp[i - 1][j2][j - num1]; &#125; &#125; &#125; &#125; &#125; int pre_j, cur_cnt; for (int i = m; i &gt;= 0; i--) &#123; for (int j = cnt; j &gt;= 0; j--) &#123; if (dp[n][i][j]) &#123; pre_j = i; cur_cnt = j; ll ans = 1LL * j * (tot - j); cout &lt;&lt; ans &lt;&lt; &quot;
&quot;; goto flag; &#125; &#125; &#125; flag: vt&lt;int&gt; choose(n + 5); choose[n] = pre_j; cur_cnt -= pref[n][pre_j]; for (int i = n - 1; i &gt;= 1; i--) &#123; for (int j = pre_j; j &gt;= 0; j--) &#123; if (dp[i][j][cur_cnt]) &#123; choose[i] = j; pre_j = j; cur_cnt -= pref[i][j]; break; &#125; &#125; &#125; // for (int i = 1; i &lt;= n; i++) &#123; // db(i), db(choose[i]), el; // &#125; string ans; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 1; j &lt;= choose[i] - choose[i - 1]; j++) &#123; ans += &#x27;R&#x27;; &#125; ans += &#x27;D&#x27;; if (i == n) &#123; for (int j = 1; j &lt;= m - choose[i]; j++) &#123; ans += &#x27;R&#x27;; &#125; &#125; &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; 代码(正解): #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int n, m; cin &gt;&gt; n &gt;&gt; m; vt&lt;vt&lt;int&gt;&gt; a(n + 5, vt&lt;int&gt;(m + 5)); int tot = 0; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 1; j &lt;= m; j++) &#123; cin &gt;&gt; a[i][j]; tot += a[i][j]; &#125; &#125; int cnt = tot / 2; int cur = 0; vt&lt;int&gt; choose(n + 5); for (int i = 1; i &lt;= n; i++) &#123; for (int j = m; j &gt;= 1; j--) &#123; if (cur + a[i][j] &lt;= cnt) &#123; cur += a[i][j]; &#125; else &#123; choose[i] = j; break; &#125; &#125; choose[i] = max(choose[i], choose[i - 1]); &#125; ll ans1 = 1LL * cnt * (tot - cnt); cout &lt;&lt; ans1 &lt;&lt; &quot;
&quot;; // for (int i = 1; i &lt;= n; i++) &#123; // db(i), db(choose[i]), el; // &#125; string ans; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 1; j &lt;= choose[i] - choose[i - 1]; j++) &#123; ans += &#x27;R&#x27;; &#125; ans += &#x27;D&#x27;; if (i == n) &#123; for (int j = 1; j &lt;= m - choose[i]; j++) &#123; ans += &#x27;R&#x27;; &#125; &#125; &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;

牛客周赛 Round 130 F 题目链接: https://ac.nowcoder.com/acm/contest/127702/F 思路: 在讲解这道题之前, 我想先复习一下置换环 置换环的具体定义 置换环, 是一个有向图中的环, 我之前没有详细了解, 以为是无向图的环 置换环就是每个节点(下标)指向它应该在的位置, 对于一个排列p, i指向p[i] 对于一个环, x1 -&gt; x2 -&gt; … -&gt; xn -&gt; x1, 要拆掉这个环的方法就是
swap(p[x1], p[x2]) 这一步之后, p[x1]已经到了正确的位置, p[x2]的位置来到了x1, 但是p[x2]要去的位置仍是x3, 也就是说现在是x1 -&gt; x3, 相当于只是把x2从环中拿掉 swap(p[x1], p[x3]) … swap(p[x1], p[xn])
这里总共有n - 1次操作, 执行完之后, x2, x3, …, xn都从环中拿掉, 各自变成自环, 而x1也变成自环, 也就是说环中元素都到了各自正确的位置 最小交换次数 怎么证明交换次数最优就是n - 1次呢, 其实我不会严格证明, 我说一个朴素的理解吧, 首先我已经找到了一个方法, 保证每次交换能让一个元素回到正确位置, 要更优的话, 只能说是一次交换让两个元素回到了正确位置, 两个就是上限了, 因为每次交换只影响两个元素, 所以不可能说我一次交换让大于两个的元素回到正确位置, 但是如果说我一次交换让两个元素回到了正确位置, 说明这两个元素本身就是一整个环, 它们不可能在这个大的环里面, 可能我只需要证明说, 我这个让一个元素到正确位置的操作, 能保证让这个环不被拆掉, 那好像就挺显然的, 因为我要是想使得一个元素到达正确位置, 我必然是选择xi -&gt; x{i+1}这样的一条边, 来进行交换, 这个操作我上面已经说明过, 相当于是把x{i+1}这个节点拿掉, 环的大小只是减小1, 结构没有发生大的改变, 所以n - 1次就是最优的做法 最小交换次数的公式变换 假设一个排列对应着k个环, 那么最小交换次数的计算公式就是 $$ \sum_{i = 1} ^ {k} {(size(cycle_i) - 1)} $$ 其实所有的环size总和就是n, 所以公式也可以变成 n − k 如何合并环 合并环的具体操作其实就是, 从两个不同的环当中各自选择一个元素, 进行交换, 就可以合并, 下面做一个粗略的证明 假设有两个环 x1 -&gt; x2 -&gt; x3 -&gt; … -&gt; xn -&gt; x1 y1 -&gt; y2 -&gt; y3 -&gt; … -&gt; ym -&gt; y1 我交换p[xi]和p[yj] 交换这个操作, 实际上是交换各自的出边, 因为环中节点的值表示的是下标, 你交换两个元素, 不影响其他元素要达到的位置, 当时被交换的两个元素, 所在的下标不同了, 所以对应下标要去的位置也不同了 交换了p[xi]和p[yj], 原本xi -&gt; x{i + 1}, yj -&gt; y{j + 1} 现在变成了xi -&gt; y{j + 1}, yj -&gt; x{i + 1} 于是这个环变成 x1 -&gt; x2 -&gt; … -&gt; x{i - 1} -&gt; x_i -&gt; y{j + 1} -&gt; y{j + 2} -&gt; … -&gt; ym -&gt; y1 -&gt; … -&gt; y{j - 1} -&gt; yj -&gt; x{i + 1} -&gt; x_{i + 2} -&gt; … -&gt; xn -&gt; x1 题目思路 好了, 搞定背景知识之后, 回到这个题目当中来, 根据题意, 我们很显然可以得到, 要使得混乱度变成2的话, 就是把排列顺序排, 然后有两个相邻的元素错位了, 现在要看所有错位的排序当中, 哪个交换次数最少, 我们遍历i和i + 1, 看i和i + 1是否在一个环当中, 如果在同一个环当中, 那么我们就留着这两个元素在环中不拿掉, 这样就比拆掉这个环的代价少1 假设使得排列有序的代价是c好了, 那么第一种情况的代价就是c-1 现在我们讨论, i和i+1不在同一个环的代价是多少, 我们先考虑一个做法, 把i和i + 1所在的两个环合并, 按照上面的说法, 我们只需要选择两个环中的元素进行交换即可, 那么代价是多少呢, 假设i所在的环size是a, i+1所在的环size是b, 合并的代价是1, 然后拆掉这个大环并保留i和i+1的代价是a+b-2, 总共的代价就是a+b-1, 原本使得排列有序的代价应该是a-1+b-1=a+b-2, 现在代价多1, 总代价就是c+1 这里我们可能会想有没有第三种可能, 使得代价是c, 也就是不变, 这个是不可能的, 我们证明一下这件事情 引理: 每次交换相邻的元素, 必然产生或减少一个逆序对, 这个很显然, 不证明了 交换任意两个元素, 逆序对的数量增减必然是奇数 考虑交换a_i, a_j ai, a{i+1}, …, a_j a_i一直交换到, a_j的位置是j-i次交换 之后数组变成 a{i+1}, a{i+2}, …, a_j, a_i aj交换到a{i+1}的交换次数是j-i-1, 少了一个a_i, 其他都和a_i交换过的重叠, 所以是j-i-1 总的交换次数就是, 2*(j-i)-1, 是奇数 所以代价只可能是c-1, c+1, c-3, c+3, …, c是不可能的 代码(暴力) 思路是交换i和i+1的位置, 然后求有序的最小交换次数 #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queue// 1-baseclass DSU &#123;private: vector&lt;int&gt; f, siz; int n;public: DSU(int _n) &#123; this-&gt;n = _n; f.resize(_n + 1); siz.assign(_n + 1, 1); iota(f.begin(), f.end(), 0); &#125; int find(int x) &#123; if (f[x] == x) return x; return f[x] = find(f[x]); &#125; void merge(int x, int y) &#123; x = find(x); y = find(y); if (x == y) return; f[y] = x; siz[x] += siz[y]; &#125; bool same(int x, int y) &#123; return find(x) == find(y); &#125; int size(int x) &#123; return siz[find(x)]; &#125;&#125;;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5), pos(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; pos[a[i]] = i; &#125; ll ans = 1e18; for (int t = 1; t + 1 &lt;= n; t++) &#123; int x = pos[t]; int y = pos[t + 1]; auto b = a; swap(b[x], b[y]); DSU dsu(n); for (int i = 1; i &lt;= n; i++) &#123; dsu.merge(i, b[i]); &#125; ll cnt = 0; for (int i = 1; i &lt;= n; i++) &#123; if (dsu.find(i) == i) &#123; cnt += dsu.size(i) - 1; &#125; &#125; ans = min(ans, cnt); &#125; cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; 代码(正解) #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; vt&lt;int&gt; bel(n + 5); int cnt = 0; for (int i = 1; i &lt;= n; i++) &#123; if (bel[i]) continue; int cur = i; cnt++; while (!bel[cur]) &#123; bel[cur] = cnt; cur = a[cur]; &#125; &#125; int ans = n - cnt + 1; for (int i = 1; i + 1 &lt;= n; i++) &#123; if (bel[i] == bel[i + 1]) &#123; ans = n - cnt - 1; break; &#125; &#125; cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;

比赛链接: https://ac.nowcoder.com/acm/contest/128672 C 思路: 我想了一会, 想到一个思路就是记录连续gcd为1的块, 然后修改次数就是块长/2, 修改数字的话就修改成所有质因数相乘就行, 这样就能保证修改其中一个, 与其相邻的就不用改, 但是这个思路有问题, 就是1是必须要改的, 你修改与1相邻的数, 最后gcd还是1, 所以1是必须改的 代码: #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; int cur = 1; ll ans = a[1] == 1; // 1是一个反例,修改了它旁边的数gcd还是1 for (int i = 2; i &lt;= n; i++) &#123; if (a[i] == 1) &#123; cur = 1; ans++; continue; &#125; if (__gcd(a[i], a[i - 1]) == 1) &#123; if (a[i - 1] == 1) &#123; continue; &#125; cur++; &#125; else &#123; ans += cur / 2; cur = 1; &#125; &#125; // db(cur), el; ans += cur / 2; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; E 思路: 我本来是想dp的, 虽然我知道题目有可能是a&gt;b, 但是其实a&lt;b的情况, dp也不一定对, 我dp的思路是这样的, 从小到大遍历, 然后翻转和+k的操作都从比i小的转移, 但是有一种情况就是a翻转成一个比a小的数, 然后再进行加的操作, 所以可以考虑bfs, 只需要考虑10b以内的范围, 因为大于等于10b的再翻转也不会比b小, 是没有意义的 代码: #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int a, b, k; cin &gt;&gt; a &gt;&gt; b &gt;&gt; k; vt&lt;int&gt; ans(10 * b + 5, 1e9); queue&lt;int&gt; q; q.push(a); ans[a] = 0; while (!q.empty()) &#123; int u = q.front(); q.pop(); int nx1 = u + k; if (nx1 &lt;= 10 * b) &#123; if (ans[nx1] == (int)1e9) &#123; q.push(nx1); ans[nx1] = ans[u] + 1; &#125; &#125; if (u % 10) &#123; string rsu = to_string(u); reverse(all(rsu)); int ru = stoi(rsu); if (ru &lt;= 10 * b) &#123; if (ans[ru] == (int)1e9) &#123; q.push(ru); ans[ru] = ans[u] + 1; &#125; &#125; &#125; &#125; if (ans[b] &gt;= (int)1e9) &#123; cout &lt;&lt; &quot;-1
&quot;; &#125; else &#123; cout &lt;&lt; ans[b] &lt;&lt; &quot;
&quot;; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;

Codeforces Round 1084 (Div. 3) F 题意: 有n个粒子, 每个粒子有两个属性x, y, x是能量值, y是能与之共存的粒子数, 另外商店里面还有m个粒子, 问在买入商店的第i个粒子之后, 最大的能量总值是多少 思路: 假设我们要k个粒子的话, 那么这k个粒子的y都不小于k-1, 我们反向枚举k, 因为k值越小, 候选的粒子数越多, 然后选择x最大的k个粒子, 这样我们就能求出不考虑从商店买粒子的情况下的最大值. 考虑商店, 我们维护一个集合, f[k]表示k个粒子的情况排除掉最小的一个, 给商店的例子腾出一个位置, 商店粒子的可以放在f[1]到f[y+1]的集合里面, 我们要从中选一个最大的, 那么维护一个前缀最大值即可 代码: #include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123; int n, m; cin &gt;&gt; n &gt;&gt; m; vt&lt;vt&lt;ll&gt;&gt; adj(n + 5); priority_queue&lt;ll, vt&lt;ll&gt;, greater&lt;&gt;&gt; q; for (int i = 1; i &lt;= n; i++) &#123; ll x, y; cin &gt;&gt; x &gt;&gt; y; adj[y].push_back(x); &#125; ll cur = 0; for (auto t : adj[n]) &#123; q.push(t); cur += t; &#125; while (sz(q) &gt; n + 1) &#123; cur -= q.top(); q.pop(); &#125; vt&lt;ll&gt; pref(n + 5); if (sz(q) == n + 1) &#123; pref[n + 1] = cur - q.top(); &#125; else &#123; pref[n + 1] = cur; &#125; vt&lt;ll&gt; cnt(n + 5); cnt[n + 1] = cur; ll oans = cur; for (int k = n; k &gt;= 1; k--) &#123; for (auto t : adj[k - 1]) &#123; if (sz(q) == k) &#123; if (q.top() &lt; t) &#123; cur -= q.top(); cur += t; q.pop(); q.push(t); &#125; &#125; else &#123; q.push(t); cur += t; &#125; &#125; while (sz(q) &gt; k) &#123; cur -= q.top(); q.pop(); &#125; ll t; if (sz(q) == k) &#123; t = cur - q.top(); &#125; else &#123; t = cur; &#125; pref[k] = t; cnt[k] = cur; oans = max(oans, cnt[k]); &#125; // cout &lt;&lt; oans &lt;&lt; &quot;
&quot;; // for (int i = 1; i &lt;= n + 1; i++) &#123; // cout &lt;&lt; pref[i] &lt;&lt; &quot; 
&quot;[i == n + 1]; // &#125; for (int i = 2; i &lt;= n + 1; i++) &#123; pref[i] = max(pref[i], pref[i - 1]); &#125; for (int i = 1; i &lt;= m; i++) &#123; ll x, y; cin &gt;&gt; x &gt;&gt; y; // db(x), db(pref[y + 1]), el; cout &lt;&lt; max(oans, x + pref[y + 1]) &lt;&lt; &quot; &quot;; &#125; cout &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(0); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;

牛客练习赛149
C
题目链接：https://ac.nowcoder.com/acm/contest/129232/C
思路：我一开始用dp，就是计算到达每个gcd的最小价值，然后枚举gcd，选择价值总和最小的，但是超时了，可能是map的时间复杂度和常数太大了，不然我没看出来和标解的时间复杂度差多少，正确的做法应该是bfs
代码（超时）：
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123;    int n, m;    cin &gt;&gt; n &gt;&gt; m;    vt&lt;int&gt; a(n + 5), b(m + 5);    int mx = 0;    // cerr &lt;&lt; &quot;hi\n&quot;;    for (int i = 1; i &lt;= n; i++) &#123;        cin &gt;&gt; a[i];        mx = max(mx, a[i]);    &#125;    for (int i = 1; i &lt;= m; i++) &#123;        cin &gt;&gt; b[i];    &#125;    // cerr &lt;&lt; &quot;hi\n&quot;;    vt&lt;int&gt; cnt(mx + 5);    vt&lt;ll&gt; cnt2(mx + 5);    set&lt;int&gt; g_factors;    for (int i = 1; i &lt;= n; i++) &#123;        map&lt;int, int&gt; dp;        dp[a[i]] = 0;        // cerr &lt;&lt; &quot;hi&quot; &lt;&lt; endl;        set&lt;int&gt; cur_factors = &#123;a[i]&#125;;        for (int j = 1; j &lt;= m; j++) &#123;            for (auto factor : cur_factors) &#123;                if (dp.count(__gcd(b[j], factor)) == 0) &#123;                    dp[__gcd(b[j], factor)] = dp[factor] + 1;                &#125; else &#123;                    dp[__gcd(b[j], factor)] = min(dp[__gcd(b[j], factor)], dp[factor] + 1);                &#125;                cur_factors.insert(__gcd(b[j], factor));            &#125;        &#125;        for (auto factor : cur_factors) &#123;            cnt[factor]++;            cnt2[factor] += dp[factor];            g_factors.insert(factor);        &#125;    &#125;    ll ans = 1e18;    for (auto i : g_factors) &#123;        if (cnt[i] == n) &#123;            ans = min(ans, cnt2[i]);        &#125;    &#125;    if (ans == (ll)1e18) &#123;        cout &lt;&lt; &quot;-1\n&quot;;    &#125; else &#123;        cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;    &#125;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(0);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;
代码（正解）：
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long long#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define vt vector#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1#define sz(x) int((x).size())#define pii pair&lt;int, int&gt;#define pll pair&lt;ll, ll&gt;#define pb push_back#define all(x) (x).begin(), (x).end()#define fi first#define se second#define p_queue priority_queuevoid solve() &#123;    int n, m;    cin &gt;&gt; n &gt;&gt; m;    vt&lt;int&gt; a(n + 5);    vt&lt;int&gt; b(m + 5);    int mx = 0;    for (int i = 1; i &lt;= n; i++) &#123;        cin &gt;&gt; a[i];        mx = max(mx, a[i]);    &#125;    for (int i = 1; i &lt;= m; i++) &#123;        cin &gt;&gt; b[i];    &#125;    vt&lt;int&gt; dis(mx + 5, 1e9), cnt(mx + 5);    vt&lt;ll&gt; sum(mx + 5);    for (int i = 1; i &lt;= n; i++) &#123;        queue&lt;int&gt; q;        q.push(a[i]);        dis[a[i]] = 0;        cnt[a[i]]++;        vt&lt;int&gt; tmp;        while (!q.empty()) &#123;            int u = q.front();            q.pop();            tmp.pb(u);            for (int j = 1; j &lt;= m; j++) &#123;                int v = __gcd(b[j], u);                if (dis[v] == int(1e9)) &#123;                    dis[v] = dis[u] + 1;                    sum[v] += dis[v];                    cnt[v]++;                    q.push(v);                &#125;            &#125;        &#125;        for (auto x : tmp) &#123;            dis[x] = 1e9;        &#125;    &#125;    ll ans = 1e18;    for (int i = 1; i &lt;= mx; i++) &#123;        if (cnt[i] == n) &#123;            ans = min(ans, sum[i]);        &#125;    &#125;    if (ans == (ll)1e18) &#123;        cout &lt;&lt; &quot;-1\n&quot;;    &#125; else &#123;        cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;    &#125;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(0);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;

https://ac.nowcoder.com/acm/contest/129583/C
思路：假设我选择两个大猴子，能满意的小猴子数量应该是k[x]-k[y]-jj(x,y)，jj是交集，这里就是jj这个预处理要想到，用map来实现，然后没有交集的，也要点手法，就是如果发现所有jj集合的数量没有满的话，那必然存在没有交集的两个大猴子
代码：
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifint main() &#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int n, m;    cin &gt;&gt; n &gt;&gt; m;    vt&lt;int&gt; k(m + 5);    map&lt;pair&lt;int, int&gt;, int&gt; mp;    for (int i = 1; i &lt;= n; i++) &#123;        int a, b;        cin &gt;&gt; a &gt;&gt; b;        if (a &gt; b) &#123;            swap(a, b);        &#125;        k[a]++, k[b]++;        mp[&#123;a, b&#125;]++;    &#125;    for (int i = 1; i &lt;= m; i++) &#123;        db(i), db(k[i]), el;    &#125;    vt&lt;int&gt; ks;    vt&lt;int&gt; cnt(n + 5);    for (int i = 1; i &lt;= m; i++) &#123;        ks.pb(k[i]);        cnt[k[i]]++;    &#125;    sort(all(ks), greater&lt;&gt;());    int ans = 0;    if (cnt[ks[0]] == 1) &#123;        int cnt2=0;        for (auto [_, __] : mp) &#123;            int x = _.first;            int y = _.second;            if (k[x] &lt; k[y]) &#123;                swap(x, y);            &#125;            if (k[x] == ks[0] &amp;&amp; k[y] == ks[1]) &#123;                cnt2++;                if (x &gt; y) &#123;                    swap(x, y);                &#125;                ans = max(ans, k[x] + k[y] - mp[&#123;x, y&#125;]);            &#125;        &#125;        if(cnt2&lt;1LL*cnt[ks[0]]*cnt[ks[1]])&#123;            ans=max(ans,ks[0]+ks[1]);        &#125;    &#125; else &#123;        int cnt2=0;        for (auto [_, __] : mp) &#123;            int x = _.first;            int y = _.second;            if (k[x] == ks[0] &amp;&amp; k[y] == ks[0]) &#123;                cnt2++;                ans = max(ans, k[x] + k[y] - mp[&#123;x, y&#125;]);            &#125;        &#125;        if(cnt2&lt;1LL*cnt[ks[0]]*(cnt[ks[0]]-1)/2)&#123;            ans=max(ans,ks[0]*2);        &#125;    &#125;    cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;    return 0;&#125;

