Codeforces Round 188 (Rated for Div. 2)
E
思路：构造一个小的开头，然后我们可以推出后续的，前面的只需要计算总和是否等于枚举的开头就行
代码：
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifvoid solve() &#123;    string s;    cin &gt;&gt; s;    if (sz(s) == 1) &#123;        cout &lt;&lt; s &lt;&lt; &quot;\n&quot;;        return;    &#125;    ll sum = 0;    vt&lt;int&gt; mp(10);    for (int c : s) &#123;        c -= &#x27;0&#x27;;        mp[c]++;        sum += c;    &#125;    auto f = [&amp;](ll x) -&gt; ll &#123;        ll res = 0;        while (x) &#123;            res += x % 10;            x /= 10;        &#125;        return res;    &#125;;    for (ll short_sum = 1; ; short_sum++) &#123;        ll x = short_sum;        ll cnt = 0;        string ans = to_string(short_sum);        while (true) &#123;            if (x &lt;= 9) &#123;                cnt += f(x);                break;            &#125;            cnt += f(x);            ans += to_string(f(x));            x = f(x);        &#125;        vt&lt;int&gt; tmp;        // if (short_sum == 12) &#123;            // for (int i = 0; i &lt; 10; i++) &#123;            //     cout &lt;&lt; mp[i] &lt;&lt;&quot; \n&quot;[i == 9];            // &#125;        // &#125;        // if (short_sum == 16)        //     db(ans), el;        bool flag = true;        for (int c : ans) &#123;            c -= &#x27;0&#x27;;            if (mp[c] &gt; 0) &#123;                mp[c]--;                tmp.pb(c);                // db(c), el;            &#125; else &#123;                if (short_sum == 12) &#123;                    // for (int i = 0; i &lt; 10; i++) &#123;                    //     cout &lt;&lt; mp[i] &lt;&lt;&quot; \n&quot;[i == 9];                    // &#125;                    // db(char(c + &#x27;0&#x27;)), el;                &#125;                flag = false;                break;            &#125;        &#125;        // if (short_sum == 12) &#123;        //     // for (int i = 0; i &lt; 10; i++) &#123;        //     //     cout &lt;&lt; mp[i] &lt;&lt;&quot; \n&quot;[i == 9];        //     // &#125;        //     // db(ans), db(flag), el;        // &#125;        if (!flag) &#123;            for (int c : tmp) &#123;                // db(c);                mp[c]++;            &#125;            // el;            continue;        &#125;        ll rest = sum - cnt;        // if (short_sum == 12) &#123;        //     db(ans), db(sum), db(rest), db(short_sum), el;        // &#125;        if (rest == short_sum) &#123;            string t;            for (int c : s) &#123;                c -= &#x27;0&#x27;;                if (mp[c] &gt; 0) &#123;                    t += char(c + &#x27;0&#x27;);                    mp[c]--;                &#125;            &#125;            if (t[0] == &#x27;0&#x27;) &#123;                for (int j = 1; j &lt; sz(t); j++) &#123;                    if (t[j] != &#x27;0&#x27;)                        swap(t[0], t[j]);                &#125;            &#125;            // db(rest), db(short_sum), db(t), db(ans), el;            ans = t + ans;            cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;            return;        &#125; else &#123;            for (int c : tmp) &#123;                mp[c]++;            &#125;        &#125;    &#125;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;
Codeforces Round 1056 (Div.
2)
C
思路：考虑从位置i走到位置i+1的变化情况
有四种：

(( 增量为1
)) 增量为-1
() 增量为0
)( 增量为0

可以发现a[i]-a[i-1]都是&lt;2的，所以&gt;=2的答案为0
其他情况我们这样搞，枚举第一个位置的披风方向，然后通过增量可以推算出每个位置的披风方向，然后我们再去检查整个数组的披风方向是否合法，就是对于每个位置，左边(的总和加上)的总和+1要等于a[i]
代码:
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifconst ll MOD = 676767677;void solve() &#123;    int n;    cin &gt;&gt; n;    vt&lt;int&gt; a(n + 5);    bool flag = true;    for (int i = 1; i &lt;= n; i++) &#123;        cin &gt;&gt; a[i];        if (i &gt;= 2) &#123;            if (abs(a[i] - a[i - 1]) &gt;= 2) &#123;                flag = false;            &#125;        &#125;    &#125;    if (!flag) &#123;        cout &lt;&lt; &quot;0\n&quot;;        return;    &#125;    auto check = [&amp;](int first) -&gt; bool &#123;        string s;        s += first ? &#x27;)&#x27; : &#x27;(&#x27;;        for (int i = 2; i &lt;= n; i++) &#123;            int d = a[i] - a[i - 1];            if (!d) &#123;                s += s.back() == &#x27;(&#x27; ? &#x27;)&#x27; : &#x27;(&#x27;;            &#125; else if (d == 1) &#123;                // ((                if (s.back() == &#x27;)&#x27;)                    return false;                s += &#x27;(&#x27;;            &#125; else &#123;                // ))                if (s.back() == &#x27;(&#x27;)                    return false;                s += &#x27;)&#x27;;            &#125;        &#125;        // assert(sz(s) == n);        // db(s), el;        s = &#x27; &#x27; + s;        vt&lt;int&gt; pref(n + 5);        for (int i = 1; i &lt;= n; i++)            pref[i] = pref[i - 1] + (s[i] == &#x27;(&#x27;);        vt&lt;int&gt; suff(n + 5);        for (int i = n; i &gt;= 1; i--) &#123;            suff[i] = suff[i + 1] + (s[i] == &#x27;)&#x27;);            // db(i), db(suff[i]), db(suff[i + 1]), db(s[i] == &#x27;)&#x27;), el;        &#125;        for (int i = 1; i &lt;= n; i++) &#123;            if (!((pref[i - 1] + suff[i + 1] + 1) == a[i])) &#123;                // db(i), db(pref[i - 1]), db(suff[i + 1]), el;                return false;            &#125;        &#125;        return true;    &#125;;    int ans = 0;    for (int i = 0; i &lt; 2; i++) &#123;        ans += check(i);    &#125;    cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;

https://codeforces.com/contest/2209/problem/C
思路：应该会很自然的想到询问所有的(2k-1,2k)对，就能保证这些对里面都仅有一个0，然后询问(1,3),(1,4)，但是这样是n+2次操作，想想有没有操作是没有必要的，其实(1,2)是没有必要的，假设我们做了以上的询问，然后没有问(1,2)，再假设a[1]和a[2]都不等于0，也就是说有n个0在n-1个对里面，根据抽屉原理至少有一对有两个0，有矛盾，如果a[1]=0,a[2]!=0，这代表a[3]和a[4]不等于0，也就是说有n-1个0在n-2个对里面，同理矛盾，a[1]=0,a[2]=0，这个是没有问题的，a[1]!=0,a[2]=0，其实这个情况也会有矛盾，然后总结就是如果全部询问都是0，那么a[2]就是0
代码：
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifint ask(int i, int j) &#123;    cout &lt;&lt; &quot;? &quot; &lt;&lt; i &lt;&lt; &quot; &quot; &lt;&lt; j &lt;&lt; endl;    int res;    cin &gt;&gt; res;    return res;&#125;void solve() &#123;    int n;    cin &gt;&gt; n;    n *= 2;    for (int i = 3; i + 1 &lt;= n; i += 2) &#123;        int res = ask(i, i + 1);        if (res) &#123;            cout &lt;&lt; &quot;! &quot; &lt;&lt; i &lt;&lt; endl;            return;        &#125;    &#125;    if (ask(1, 3) || ask(1, 4)) &#123;        cout &lt;&lt; &quot;! 1&quot; &lt;&lt; endl;    &#125; else &#123;        cout &lt;&lt; &quot;! 2&quot; &lt;&lt; endl;    &#125;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;
https://ac.nowcoder.com/acm/contest/130107/E
思路：以为是思维，没想到是树上dp，dp[i]表示节点i是否是一个好点，叶子结点是好点，另外一种就是能到达至少两个好点的点也是一个好点，因为小紫能封堵小红后续的一个点，所以如果小红后续只有一个好点，小紫直接把这个点封掉就是了，所以至少需要两个，小红往回走是浪费时间，所以只需要考虑子节点，所以dp是成立的
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifvoid solve() &#123;    int n;    cin &gt;&gt; n;    vt&lt;vt&lt;int&gt;&gt; adj(n + 5);    for (int i = 1; i &lt; n; i++) &#123;        int u, v;        cin &gt;&gt; u &gt;&gt; v;        adj[u].pb(v);        adj[v].pb(u);    &#125;    vt&lt;bool&gt; dp(n + 5);    auto dfs = [&amp;](auto &amp;&amp;self, int u, int p) -&gt; void &#123;        int cnt = 0;        bool has_son = false;        for (int v : adj[u]) &#123;            if (v == p)                continue;            self(self, v, u);            cnt += dp[v];            has_son = true;        &#125;        if (!has_son)            dp[u] = true;        if (cnt &gt;= 2)            dp[u] = true;    &#125;;    dfs(dfs, 1, 0);    for (int v : adj[1]) &#123;        if (dp[v]) &#123;            cout &lt;&lt; &quot;red\n&quot;;            return;        &#125;    &#125;    cout &lt;&lt; &quot;purple\n&quot;;&#125;int main() &#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int tt;    cin &gt;&gt; tt;    while (tt--) &#123;        solve();    &#125;    return 0;&#125;

开发环境搭建 记得配置虚拟环境 安装依赖 pip install django djangorestframework django-cors-headers langchain langchain-community langchain-openai chromadb mysqlclient langchain是一个跟大模型对接的一个库, 可以切换不同的大模型 这些库居然一次性安装成功了, 没有出现任何的冲突问题, wc, gemini pro还是太强 初始化django 感觉django应该还是比flask好用, 在做毕设方面, 因为我要实现的是功能而不是性能 django-admin startproject backend . (x)django-admin startproject backend (√) 这里我还是选择多嵌套一层目录, 这是我的经验之举 django settings配置 MIDDLEWARE = [ &#x27;corsheaders.middleware.CorsMiddleware&#x27;, # 必须放在第一行 &#x27;django.middleware.common.CommonMiddleware&#x27;, ...]CORS_ALLOW_ALL_ORIGINS = True # 开发阶段允许所有跨域 ’django.middleware.common.CommonMiddleware’这个中间件的作用就是自动帮我优化一些URL的规范问题, 比如自动帮我添加斜杠, 自动添加或者移除www前缀之类的东西 配置mysql 先在本地创建一个ai_diary_db create database ai_diary_db; 然后调试的话, 我是在mysql workbench那里进行连接 用户名和密码我直接告诉你都行啊, 反正也没有什么重要的东西, 用户名root, 密码1234 创建数据库模型 class DiaryEntry(models.Model): &quot;&quot;&quot;日记条目表&quot;&quot;&quot; content = models.TextField(verbose_name=&quot;日记内容&quot;) ... 这个verbose_name, verbose是冗长的意思, verbose_name就是提供一个人类方便阅读的字段名, 在django admin后台查看字段的时候会显示verbose_name而不是content这个字段名 初始化向量数据库 在diary这个文件夹底下创建一个vector_service.py import chromadbfrom django.conf import settingsimport os# 确保向量库文件夹存在CHROMA_DATA_PATH = os.path.join( settings.BASE_DIR, &quot;chroma_db&quot;) # 到时候会把chroma_db创建在和manage.py同级的目录下class VectorStore: def __init__(self): # 确保目录存在 if not os.path.exists(CHROMA_DATA_PATH): os.makedirs(CHROMA_DATA_PATH) # 初始化持久化客户端 self.client = chromadb.PersistentClient(path=CHROMA_DATA_PATH) # 获取或创建集合（Collection） self.collection = self.client.get_or_create_collection(name=&quot;user_diary_memory&quot;) def add_memory(self, diary_id, text, metadata): &quot;&quot;&quot;向向量库添加日记记忆&quot;&quot;&quot; self.collection.add(documents=[text], metadatas=[metadata], ids=[str(diary_id)]) def query_memory(self, query_text, n_results=3): &quot;&quot;&quot;检索相关日记&quot;&quot;&quot; return self.collection.query(query_texts=[query_text], n_results=n_results)# 单例模式实例化，方便全局调用vector_db = VectorStore() 第一次用这个向量数据库, 还是要看一下代码的, 但是豆包好像看到这段代码就有点宕机了, 所以之后再看看吧 等了半天还是没有回答, 后面我用豆包的快速模式了, 终于有了回答, 反正我也只需要表面浅显的理解就可以了, 首先这个持久化客户端的意思就是数据不会丢失, 说明这个数据是存在本地的磁盘, 而并非内存里面 metadata具体对应的就是一个字典, 存着日记的对应资料 比较重要的应该是这个n_results吧, 目前是查找3个最相似的日记, 这个感觉比较少, 但是现在我也没有什么日记, 所以开发阶段先用着这个 检查是否配置成功 配置完上面的一堆东西之后, 跑一下 python manage.py runserver 如果没有报错, 那就是配置成功 第二阶段 大模型配置 获取api_key 去deepseek官网/api_keys, 然后去创建一个新的api_keys 这里我拿到的api_keys是sk-f753df9b3b4846cbbc5302e3afc9b885, 我就保存在这了, 反正没有人看 配置大模型 在diary/下创建一个ai_services.py, 代码如下 import jsonfrom langchain_openai import ChatOpenAIfrom django.conf import settingsclass AIService: def __init__(self): # 初始化模型，DeepSeek 的 API 格式与 OpenAI 一致 self.llm = ChatOpenAI( model=&quot;deepseek-chat&quot;, openai_api_key=settings.DEEPSEEK_API_KEY, openai_api_base=&quot;https://api.deepseek.com&quot;, # DeepSeek 地址 max_tokens=1024, ) def analyze_diary(self, content): &quot;&quot;&quot;核心业务算法：分析日记并生成增强数据&quot;&quot;&quot; system_prompt = &quot;&quot;&quot; 你是一个专业的心理咨询师和行为分析专家。请分析用户的日记，并以严格的 JSON 格式返回结果。 JSON 必须包含以下字段： 1. sentiment_score: -1.0 到 1.0 之间的浮点数，代表情绪极性。 2. behavior_tags: 字符串数组，提取具体行为（如：加班、运动、听歌）。 3. thinking_pattern: 简短描述用户的思维模式（如：习惯性自责、乐观积极）。 4. aesthetic_preference: 用户在日记中表现出的审美或艺术喜好。 5. summary: 50字以内的日记内容总结。 6. synthetic_queries: 生成3个用户未来可能会问到的、能通过此篇日记回答的问题。 &quot;&quot;&quot; try: # 调用 AI response = self.llm.invoke([(&quot;system&quot;, system_prompt), (&quot;human&quot;, content)]) # 解析 AI 返回的 JSON # 提示：DeepSeek 有时会返回带有 ```json ``` 的字符串，需要处理一下 res_content = response.content.strip() if res_content.startswith(&quot;```json&quot;): res_content = res_content.split(&quot;```json&quot;)[1].split(&quot;```&quot;)[0].strip() return json.loads(res_content) except Exception as e: print(f&quot;AI 分析失败: &#123;e&#125;&quot;) return None# 实例化ai_processor = AIService() 可以看到在这个日记系统里面ai扮演的角色是一个心理咨询师, 合着我文本分析还有打标签这些行为都是由大模型来完成的啊, 那我其实没有什么工作了 简要地说明一下这个文本分析的流程, 就是我后端那边在用户save日记的时候, 接口会调用大模型的分析日记这个函数, 然后得到日记的一些情绪得分还有标签这些东西, 我现在才重新注意到日记的增强字段还有合成问题居然是保存在mysql里面的, 这是为什么呢, 后面再看看吧 接口编写 from rest_framework.views import APIViewfrom rest_framework.response import Responsefrom .models import DiaryEntry, UserProfilefrom .ai_services import ai_processorfrom .vector_service import vector_dbimport jsonclass SaveDiaryView(APIView): def post(self, request): content = request.data.get(&quot;content&quot;) if not content: return Response(&#123;&quot;error&quot;: &quot;内容不能为空&quot;&#125;, status=400) # 1. 存入初步日记到 MySQL diary = DiaryEntry.objects.create(content=content) # 2. 调用 AI 进行多维分析 ai_result = ai_processor.analyze_diary(content) if ai_result: # 3. 更新 MySQL 中的增强字段 diary.sentiment_score = ai_result.get(&quot;sentiment_score&quot;, 0) diary.behavior_tags = json.dumps(ai_result.get(&quot;behavior_tags&quot;, [])) diary.summary = ai_result.get(&quot;summary&quot;, &quot;&quot;) diary.synthetic_queries = json.dumps(ai_result.get(&quot;synthetic_queries&quot;, [])) diary.save() # 4. 存入向量数据库（ChromaDB） # 增强检索逻辑：我们将 原文 + 合成查询 一起向量化 enhanced_text = f&quot;&#123;content&#125;
合成问题: &#123;&#x27; &#x27;.join(ai_result.get(&#x27;synthetic_queries&#x27;, []))&#125;&quot; vector_db.add_memory( diary_id=diary.id, text=enhanced_text, metadata=&#123; &quot;date&quot;: diary.created_at.strftime(&quot;%Y-%m-%d&quot;), &quot;sentiment&quot;: diary.sentiment_score, &#125;, ) # 5. 更新用户画像（简单逻辑示例，后续可扩展） # 找到或创建一个画像，把新提取的思维模式写进去 profile, _ = UserProfile.objects.get_or_create(id=1) # 暂时默认用户1 profile.thinking_pattern = ai_result.get(&quot;thinking_pattern&quot;, &quot;&quot;) profile.aesthetic_preference = ai_result.get(&quot;aesthetic_preference&quot;, &quot;&quot;) profile.save() return Response( &#123; &quot;message&quot;: &quot;日记已保存并经过 AI 增强处理&quot;, &quot;id&quot;: diary.id, &quot;ai_analysis&quot;: ai_result, &#125; ) 第4步就是一个embedding的操作了 debug 碰到了一个报错 D:\project\ai_diary_system\venv\Lib\site-packages\langchain_core\_api\deprecation.py:25: UserWarning: Core Pydantic V1 functionality isn&#x27;t compatible with Python 3.14 or greater. from pydantic.v1.fields import FieldInfo as FieldInfoV1Exception in thread django-main-thread:Traceback (most recent call last): File &quot;C:\Python314\Lib	hreading.py&quot;, line 1081, in _bootstrap_inner self._context.run(self.run) ~~~~~~~~~~~~~~~~~^^^^^^^^^^ File &quot;C:\Python314\Lib	hreading.py&quot;, line 1023, in run self._target(*self._args, **self._kwargs) ~~~~~~~~~~~~^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ File &quot;D:\project\ai_diary_system\venv\Lib\site-packages\django\utils\autoreload.py&quot;, line 64, in wrapper fn(*args, **kwargs) ~~^^^^^^^^^^^^^^^^^ File &quot;D:\project\ai_diary_system\venv\Lib\site-packages\django\core\management\commandsunserver.py&quot;, line 134, in inner_run self.check(**check_kwargs) ~~~~~~~~~~^^^^^^^^^^^^^^^^ File &quot;D:\project\ai_diary_system\venv\Lib\site-packages\django\core\management ase.py&quot;, line 496, in check all_issues = checks.run_checks( app_configs=app_configs, ...&lt;2 lines&gt;... databases=databases, ) File &quot;D:\project\ai_diary_system\venv\Lib\site-packages