 = os.path.join(settings.BASE_DIR, &#x27;chroma_db&#x27;)class VectorStore: def __init__(self): if not os.path.exists(CHROMA_DATA_PATH): os.makedirs(CHROMA_DATA_PATH) self.client = chromadb.PersistentClient(path=CHROMA_DATA_PATH) # 使用 SentenceTransformer 加载模型 # 该模型会自动从 hf-mirror.com 下载，约 400MB，只需下载一次 self.emb_fn = SentenceTransformerEmbeddingFunction( model_name=&quot;paraphrase-multilingual-MiniLM-L12-v2&quot; ) self.collection = self.client.get_or_create_collection( name=&quot;user_diary_memory&quot;, embedding_function=self.emb_fn ) def add_memory(self, diary_id, text, metadata): &quot;&quot;&quot;向向量库添加日记记忆&quot;&quot;&quot; self.collection.add( documents=[text], metadatas=[metadata], ids=[str(diary_id)] ) def query_memory(self, query_text, n_results=3): return self.collection.query( query_texts=[query_text], n_results=n_results )vector_db = VectorStore() 然后手动删除chroma_db这个文件夹 (venv) D:\project\ai_diary_system ackend	ests&gt;python test_ai_api.py状态码: 200返回结果: &#123; &quot;message&quot;: &quot;日记已保存并经过 AI 增强处理&quot;, &quot;id&quot;: 5, &quot;ai_analysis&quot;: &#123; &quot;sentiment_score&quot;: 0.85, &quot;behavior_tags&quot;: [ &quot;调试&quot;, &quot;开发&quot;, &quot;散步&quot; ], &quot;thinking_pattern&quot;: &quot;积极探索型&quot;, &quot;aesthetic_preference&quot;: &quot;现代主义&quot;, &quot;summary&quot;: &quot;这是调试状态下的模拟摘要&quot;, &quot;synthetic_queries&quot;: [ &quot;测试问题1&quot;, &quot;测试问题2&quot;, &quot;测试问题3&quot; ] &#125;&#125; 然后确实在debug模式下成功返回了 然后在实际环境下还是报错了, 看来必须得充钱了, 浅浅冲个10块钱吧, 听说这样就可以用很久了, 反正寒假有赚钱打工, 我还是不心疼的, 妈的怎么要实名认证 借别人的不太好搞, 首先是未来可能室友也要用到deepseek怎么办, 另外就是我发现这个api网页需要频繁登录, 如果将实名认证绑定到我这里肯定是不太好的, 这样的话就是要登录室友的微信, 也很麻烦 听说有一个平台叫硅基流动, 上面有很多大模型可以用, 然后也支持回乡证的认证 新的api_key: sk-ydqqxiquihwhrfjlymgspqilprkhzmsiubvdhrdhmsckvsfb # backend/backend/settings.py# 1. 填入你在硅基流动申请的 API KeySILICONFLOW_API_KEY = &quot;你的_SILICON_FLOW_KEY&quot;# 2. 建议使用的模型名称（硅基流动的命名规则）# deepseek-ai/DeepSeek-V3 (推荐，生成JSON稳定)# deepseek-ai/DeepSeek-R1 (推理模型，会有思维链)AI_MODEL_NAME = &quot;deepseek-ai/DeepSeek-V3&quot; ai_services.py import jsonimport refrom langchain_openai import ChatOpenAIfrom django.conf import settingsclass AIService: def __init__(self): # 切换到硅基流动后端 self.llm = ChatOpenAI( model=settings.AI_MODEL_NAME, openai_api_key=settings.SILICONFLOW_API_KEY, openai_api_base=&#x27;https://api.siliconflow.cn/v4&#x27;, max_tokens=1024, temperature=0.7 ) def analyze_diary(self, content): # ... (之前的 system_prompt 逻辑保持不变) system_prompt = &quot;&quot;&quot; 你是一个专业的心理咨询师和行为分析专家。请分析用户的日记，并以严格的 JSON 格式返回结果。 JSON 必须包含以下字段： 1. sentiment_score: -1.0 到 1.0 之间的浮点数。 2. behavior_tags: 字符串数组。 3. thinking_pattern: 字符串。 4. aesthetic_preference: 字符串。 5. summary: 字符串。 6. synthetic_queries: 字符串数组。 注意：只输出 JSON 块，不要包含任何解释文字。 &quot;&quot;&quot; try: response = self.llm.invoke([ (&quot;system&quot;, system_prompt), (&quot;human&quot;, content) ]) raw_text = response.content.strip() # 硅基流动返回 V3 模型非常标准，通常不需要复杂的正则，但保留正则更稳 clean_text = re.sub(r&#x27;&lt;think&gt;.*?&lt;/think&gt;&#x27;, &#x27;&#x27;, raw_text, flags=re.DOTALL).strip() json_match = re.search(r&#x27;\&#123;.*\&#125;&#x27;, clean_text, re.DOTALL) if json_match: return json.loads(json_match.group()) return None except Exception as e: print(f&quot;硅基流动 API 调用失败: &#123;e&#125;&quot;) return None def chat_with_memory(self, query, context_docs): &quot;&quot;&quot;第三阶段核心：利用检索到的记忆进行对话&quot;&quot;&quot; # 构造背景资料字符串 context_str = &quot;&quot; for i, doc in enumerate(context_docs): context_str += f&quot;
记忆片段&#123;i+1&#125; (日期: &#123;doc[&#x27;metadata&#x27;].get(&#x27;date&#x27;)&#125;): &#123;doc[&#x27;content&#x27;]&#125;
&quot; system_prompt = f&quot;&quot;&quot; 你是一个拥有用户长期记忆的智能日记助手。 以下是从用户历史日记中检索出的相关记忆： &#123;context_str&#125; 请结合这些记忆回答用户的问题。 要求： 1. 优先使用记忆中的事实。 2. 如果记忆中没有相关内容，请礼貌地告知用户你还没记下这件事。 3. 语气要亲切、像一个老朋友。 &quot;&quot;&quot; try: response = self.llm.invoke([ (&quot;system&quot;, system_prompt), (&quot;human&quot;, query) ]) return response.content except Exception as e: return f&quot;对话引擎故障: &#123;e&#125;&quot;ai_processor = AIService() 听说免费送了14元的额度, 卧槽更赚了 上面那个api地址的v4要改成v1, 虽然不知道为什么, 我两个地址在浏览器上搜索的时候都是显示not found, 但是v1这个是有返回结果的 返回的结果是用英文回答的, 建议在system_prompt那里添加用中文回答的要求 他妈的, 根本没有免费额度啊, 还是得充钱, 现在我的额度显示是负数, 笑死了, 结果就只让我用一次, 用一次扣了我0.0012, 十块钱钱我能用8000多次, 根本用不完啊 原来是要在analyze_diary这里修改system_prompt才能显示中文啊 def analyze_diary(self, content): # ... (之前的 system_prompt 逻辑保持不变) system_prompt = &quot;&quot;&quot; 你是一个专业的心理咨询师和行为分析专家。请分析用户的日记，并以严格的 JSON 格式返回结果。 【重要约束】： 1. 必须且只能输出 JSON 块，不要包含任何解释性文字。 2. JSON 内部所有字段的“值”（Value）必须使用【简体中文】。 JSON 必须包含以下字段： 1. sentiment_score: -1.0 到 1.0 之间的浮点数，代表情绪极性。 2. behavior_tags: 字符串数组，提取具体行为标签（必须用中文）。 3. thinking_pattern: 字符串，简短描述用户的思维模式（必须用中文）。 4. aesthetic_preference: 字符串，描述用户的审美或艺术喜好（必须用中文）。 5. summary: 字符串，50字以内的日记内容总结（必须用中文）。 6. synthetic_queries: 字符串数组，生成3个用户未来可能会提问的问题（必须用中文）。 &quot;&quot;&quot; 第三阶段 终于到这里了, 整理完前面那堆屎了 添加了一个新的view class DiaryChatView(APIView): def post(self, request): query = request.data.get(&quot;query&quot;) if not query: return Response(&#123;&quot;error&quot;: &quot;提问内容不能为空&quot;&#125;, status=400) # 1. Retrieval：从向量库检索最相关的 3 条记忆 # ChromaDB 会自动将 query 文本转为向量进行匹配 results = vector_db.query_memory(query, n_results=3) # 2. 格式化结果 context_docs = [] if results and results[&quot;documents&quot;] and len(results[&quot;documents&quot;][0]) &gt; 0: for i in range(len(results[&quot;documents&quot;][0])): context_docs.append( &#123; &quot;content&quot;: results[&quot;documents&quot;][0][i], &quot;metadata&quot;: results[&quot;metadatas&quot;][0][i], &#125; ) # 3. Generation：结合检索到的记忆，调用 AI 生成回答 answer = ai_processor.chat_with_memory(query, context_docs) return Response( &#123; &quot;query&quot;: query, &quot;answer&quot;: answer, &quot;source_memories&quot;: context_docs, # 返回来源，证明 AI 没瞎编 &#125; ) 现在我要测试rag的检索是否能够正常运作, 现在我修改一下test_save_api.py, 注入一个内容比较丰富的日记 test_save_api.py import requestsimport jsonurl = &quot;http://127.0.0.1:8000/api/diary/save/&quot;data = &#123; &quot;content&quot;: &quot;今天在澳门大三巴后面的一家小店买了一个特别的冰箱贴，是路飞拿着葡挞的图案。我把它送给了我的好朋友小明，希望他喜欢这个毕业礼物。&quot;&#125;try: response = requests.post(url, json=data) print(&quot;状态码:&quot;, response.status_code) print(&quot;返回结果:&quot;, json.dumps(response.json(), indent=4, ensure_ascii=False))except Exception as e: print(&quot;请求失败:&quot;, e) 然后再编写一个test_rag.py来测试ai在回答问题的时候是否能够找到相关的依据 test_rag.py import requestsimport jsonurl = &quot;http://127.0.0.1:8000/api/diary/chat/&quot;# 问一个日记里才有的细节data = &#123;&quot;query&quot;: &quot;我送给小明的毕业礼物是什么样子的？&quot;&#125;try: response = requests.post(url, json=data) result = response.json() print(&quot;
