=== 检索依据 ===&quot;) for idx, m in enumerate(result.get(&quot;source_memories&quot;, [])): print(f&quot;依据&#123;idx+1&#125;: &#123;m[&#x27;content&#x27;]&#125;&quot;)except Exception as e: print(&quot;请求失败:&quot;, e) chatview也进行了一些修改, 添加了重排序算法的实现 class DiaryChatView(APIView): def post(self, request): query = request.data.get(&quot;query&quot;) if not query: return Response(&#123;&quot;error&quot;: &quot;提问内容不能为空&quot;&#125;, status=400) try: # 1. Retrieval：从向量库检索候选（先取 10 条） results = vector_db.query_memory(query, n_results=10) # 检查是否有检索结果 if ( not results or not results[&quot;documents&quot;] or len(results[&quot;documents&quot;][0]) == 0 ): return Response( &#123; &quot;query&quot;: query, &quot;answer&quot;: &quot;我的记忆库里目前还没有相关的记录呢。&quot;, &quot;source_memories&quot;: [], &#125; ) # 2. 自定义重排序算法 (Re-ranking) scored_docs = [] today = date.today() for i in range(len(results[&quot;documents&quot;][0])): # 获取相似度得分（ChromaDB 返回距离，越小越相似） dist = results[&quot;distances&quot;][0][i] if &quot;distances&quot; in results else 1.0 sim_score = 1.0 / (1.0 + dist) # 获取元数据 meta = results[&quot;metadatas&quot;][0][i] content = results[&quot;documents&quot;][0][i] # 健壮性处理：如果元数据缺失则赋默认值 try: diary_date_str = meta.get(&quot;date&quot;, today.strftime(&quot;%Y-%m-%d&quot;)) diary_date = datetime.datetime.strptime( diary_date_str, &quot;%Y-%m-%d&quot; ).date() sentiment = abs(float(meta.get(&quot;sentiment&quot;, 0))) except: diary_date = today sentiment = 0 # 计算时间衰减 (每过 100 天权重减半的效果) days_diff = (today - diary_date).days time_decay = 1.0 / (1.0 + 0.01 * days_diff) # 核心公式计算 final_score = (sim_score * 0.5) + (time_decay * 0.3) + (sentiment * 0.2) scored_docs.append( &#123;&quot;content&quot;: content, &quot;metadata&quot;: meta, &quot;final_score&quot;: final_score&#125; ) # 按总分排序 scored_docs.sort(key=lambda x: x[&quot;final_score&quot;], reverse=True) context_docs = scored_docs[:3] # 3. 调用 AI answer = ai_processor.chat_with_memory(query, context_docs) return Response( &#123;&quot;query&quot;: query, &quot;answer&quot;: answer, &quot;source_memories&quot;: context_docs&#125; ) except Exception as e: # 这里的报错会直接显示在控制台和返回结果里 import traceback traceback.print_exc() return Response(&#123;&quot;error&quot;: f&quot;系统内部错误: &#123;str(e)&#125;&quot;&#125;, status=500) 我也不太清楚发生了什么, 一开始测试了一下rag的效果, 然后发现ai返回了None, 问了ai进行了一些调试之后, 准备打印一些调试信息, 结果再跑一次test_rag就成功了 首先是存一篇日记 data = &#123; &quot;content&quot;: &quot;今天在澳门大三巴后面的一家小店买了一个特别的冰箱贴，是路飞拿着葡挞的图案。我把它送给了我的好朋友小明，希望他喜欢这个毕业礼物。&quot;&#125; 内容大概是这样的 test_rag.py import requestsimport jsonurl = &quot;http://127.0.0.1:8000/api/diary/chat/&quot;# 问一个日记里才有的细节data = &#123;&quot;query&quot;: &quot;我送给小明的毕业礼物是什么样子的？&quot;&#125;try: response = requests.post(url, json=data) result = response.json() print(&quot;
