=== 检索依据 ===&quot;) for idx, m in enumerate(result.get(&quot;source_memories&quot;, [])): print(f&quot;依据&#123;idx+1&#125;: &#123;m[&#x27;content&#x27;]&#125;&quot;)except Exception as e: print(&quot;请求失败:&quot;, e) 跑完test_rag.py的结果是 (venv) D:\project\ai_diary_system ackend	ests&gt;python test_rag.py=== 用户提问 ===我送给小明的毕业礼物是什么样子的？=== AI 回答 ===哈哈，我记得很清楚呢！你送给小明的是一个特别可爱的冰箱贴，是在澳门大三巴后面那家小店买的。图案是路飞拿着葡挞，既融入了《海贼王 》的元素，又有澳门特色葡挞，真的很有创意！这个礼物既特别又实用，小明收到一定很开心吧？😊（根据2026-03-07的记忆片段1回答）=== 检索依据 ===依据1: 今天在澳门大三巴后面的一家小店买了一个特别的冰箱贴，是路飞拿着葡挞的图案。我把它送给了我的好朋友小明，希望他喜欢这个毕业礼物。合成问题: 如何挑选有意义的纪念品？ 澳门有哪些特色文创小店？ 送什么毕业礼物既特别又实用？依据2: 今天心情挺好的，毕设环境终于调通了。虽然中间遇到了 Python 版本的问题，但在努力下还是解决了。下午打算去公园散散步，听听轻音乐。合成问题: 测试问题1 测试问题2 测试问题3依据3: 今天心情挺好的，毕设环境终于调通了。虽然中间遇到了 Python 版本的问题，但在努力下还是解决了。下午打算去公园散散步，听听轻音乐。合成问题: 如何更好地调试Python环境问题？ 散步对心情有哪些积极影响？ 有哪些适合散步时听的轻音乐推荐？ 第四阶段 多维人物画像 现在我要干的事情就是多存一点日记, 给ai更多的个人资料 大概存这样的两篇日记吧 日记 A：“今天代码又报错了，调了一上午没过，心烦意乱。下午去买了个蛋挞吃，心情瞬间好了很多。”日记 B：“最近每当遇到实验数据对不上的时候，我就想去吃个葡挞。看来甜食真的是我的减压神器。” 甚至可以多存几遍, 让ai能够发现规律 然后是创建一个services.py, 在diary目录底下 services.py import jsonfrom .models import DiaryEntry, UserProfilefrom .ai_services import ai_processorclass ProfileService: @staticmethod def update_user_portrait(days=30): &quot;&quot;&quot;核心业务算法：从历史记录中聚合多维画像&quot;&quot;&quot; # 1. 提取最近一段时间的增强数据 entries = DiaryEntry.objects.all().order_by(&quot;-created_at&quot;)[:days] if not entries: return &quot;数据不足，无法生成画像。&quot; # 2. 准备聚合素材 context_data = [] for e in entries: context_data.append( &#123; &quot;tags&quot;: e.behavior_tags, &quot;sentiment&quot;: e.sentiment_score, &quot;summary&quot;: e.summary, &#125; ) # 3. 调用 AI 进行模式分析 (这是导师最看重的逻辑推演) analysis_prompt = f&quot;&quot;&quot; 你是一个行为心理学专家。下面是用户最近一段时间的日记分析记录： &#123;json.dumps(context_data, ensure_ascii=False)&#125; 请根据这些数据，更新并输出用户的【多维画像报告】。 要求以 JSON 格式输出，包含以下维度： 1. behavior_patterns: 数组。识别重复出现的行为链条（例如：遇到压力 -&gt; 消费甜食）。 2. thinking_habits: 字符串。总结用户的思维惯性（如：遇到困难倾向于自责还是寻找替代方案）。 3. stress_response: 字符串。用户如何应对负面情绪。 4. consistency_analysis: 字符串。近期情绪与行为的一致性评价。 5. suggestion: 针对用户画像给出的 3 条具体行为改进建议。 注意：请始终使用中文回答。 &quot;&quot;&quot; try: # 复用 ai_processor 的 invoke 方法逻辑 response = ai_processor.llm.invoke( [(&quot;system&quot;, analysis_prompt), (&quot;human&quot;, &quot;请生成我的最新画像&quot;)] ) # 解析并更新到 UserProfile 模型 # 此处逻辑与 analyze_diary 类似，提取 JSON 块 import re clean_text = re.sub( r&quot;&lt;think&gt;.*?&lt;/think&gt;&quot;, &quot;&quot;, response.content, flags=re.DOTALL ).strip() json_match = re.search(r&quot;\&#123;.*\&#125;&quot;, clean_text, re.DOTALL) if json_match: portrait_json = json.loads(json_match.group()) # 更新数据库 profile, _ = UserProfile.objects.get_or_create(id=1) profile.portrait_data = portrait_json profile.save() return portrait_json return None except Exception as e: print(f&quot;画像聚合失败: &#123;e&#125;&quot;) return Noneprofile_service = ProfileService() 这个程序的作用就是根据过去N篇日记的碎片化内容, 糅合成一个完整的数字化人格出来 然后又创建了一个新的接口, 用来一键生成人物画像 class UserInsightView(APIView): def get(self, request): &quot;&quot;&quot;获取生成的画像洞察报告&quot;&quot;&quot; # 触发一次实时聚合（实际生产中可改为定时任务） portrait = profile_service.update_user_portrait() if not portrait: return Response(&#123;&quot;error&quot;: &quot;画像数据生成失败&quot;&#125;, status=500) return Response(&#123;&quot;status&quot;: &quot;success&quot;, &quot;persona_report&quot;: portrait&#125;) 第五阶段 情绪趋势预测还有前端可视化 也是新建一个view, 这里是生成一些数据, 方便前端进行绘图 class SentimentTrendView(APIView): def get(self, request): &quot;&quot;&quot;获取情感波动趋势数据，用于前端绘图&quot;&quot;&quot; # 取最近 14 天的记录 entries = DiaryEntry.objects.all().order_by(&#x27;created_at&#x27;)[:14] data = [] for e in entries: data.append(&#123; &quot;date&quot;: e.created_at.strftime(&#x27;%m-%d&#x27;), &quot;score&quot;: e.sentiment_score &#125;) # 简单的线性预测逻辑（毕设亮点：自主预测算法） prediction = &quot;平稳&quot; if len(data) &gt;= 3: recent_scores = [d[&#x27;score&#x27;] for d in data[-3:]] if all(recent_scores[i] &gt; recent_scores[i+1] for i in range(len(recent_scores)-1)): prediction = &quot;下滑风险&quot; elif all(recent_scores[i] &lt; recent_scores[i+1] for i in range(len(recent_scores)-1)): prediction = &quot;持续上升&quot; return Response(&#123; &quot;trend&quot;: data, &quot;prediction&quot;: prediction, &quot;advice&quot;: &quot;根据趋势，建议您保持目前的作息。&quot; if prediction != &quot;下滑风险&quot; else &quot;检测到情绪下滑趋势，建议今晚早点休息并听一段莫扎特。&quot; &#125;) 现在要开始写前端了 安装一些依赖 # 使用 pnpm 创建 Vite 项目pnpm create vite frontend --template vuecd frontend# 安装基础依赖pnpm install# 安装我们项目需要的特有依赖pnpm add axios echarts element-plus lucide-vue-next 然后经过ai的一堆骚操作, 前端页面就出来了, 但是现在这个页面还有很多的问题, 比如看不到历史日记内容, 还有ai好像是一个智障 ai在回答问题的时候, 在没有完全明确证据的情况下, 它不敢做出推断, 所以这里修改了一下prompt system_prompt = f&quot;&quot;&quot; 你是一个拥有超强洞察力的智能日记助手。你不仅记得用户写下的每一件事，还能通过细节推断用户的喜好。 以下是从用户历史日记中检索出的【绝对真实】的记忆片段： &#123;context_str&#125; 【回复指令】： 1. 深度检索：即使日记里没有直接说“我喜欢XX”，但如果提到了“吃了XX心情变好”、“反复去买XX”，你就要果断判定这是用户的喜好。 2. 引用证据：回答时要具体说出是哪一天的记录。例如：“在3月7日的记录里，你提到...” 3. 拒绝模棱两可：不要说“好像没有记录”，除非记忆片段真的完全无关。只要有相关线索，就给出一个肯定的、温暖的观察报告。 4. 语气：你是老朋友，说话要亲切、俏皮，多用表情符号。 5. 语言：必须使用简体中文。 &quot;&quot;&quot; 今天就这里结束吧, ai的prompt和算法方面可能还是有一点问题, 但是整体上我想要呈现的效果已经显示出来了, 剩下的就是调整一些参数而已了, 然后剩下的就是继续完善这个前端页面, 加入一个用户登录系统来区分不同的用户, 然后添加这个日记增删改查的接口, 后续可能还会考虑把这个项目部署到服务器上面去, 唉, 唯一的感想就是ai实在是太牛逼了, 帮天时间干了我一个月的工作量, 而且这个gemini写的代码bug还不多, 居然能跑起来, 比chatgpt要强太多了, 而且在ai studio这里还是免费的

https://codeforces.com/contest/2224/problem/D 简单的来说就是统计i&lt;j,c[i]&gt;c[j]的期望，代入得到a[i]*b[i]&gt;a[j]*b[j]，也就是a[i]/a[j] &gt; b[j]/b[i] a[i]/a[j]是固定的，不管了 然后b的元素是任意选的所以我们先枚举所有的组合，从小到大按顺序排 a[i]/a[j] &gt; x/y，x和y是从b的组合里面任意选的，我们就二分去找最小的x/y &lt; a[i]/a[j]，然后除以n*(n-1)，加在一起 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifconst ll MOD = 998244353;ll power(ll u, ll v) &#123; ll res = 1; while (v) &#123; if (v &amp; 1) res = res * u % MOD; u = u * u % MOD; v &gt;&gt;= 1; &#125; return res;&#125;ll inv(ll x) &#123; return power(x, MOD - 2); &#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;ll&gt; a(n + 5), b(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; b[i]; &#125; vt&lt;pair&lt;ll, ll&gt;&gt; tmp; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 1; j &lt;= n; j++) &#123; if (i == j) &#123; continue; &#125; tmp.pb(&#123;b[i], b[j]&#125;); &#125; &#125; sort(all(tmp), [&amp;](auto x, auto y) &#123; return x.first * y.second &lt; y.first * x.second; &#125;); ll fenmu = inv(n * (n - 1)); ll ans = 0; for (int i = 1; i &lt; n; i++) &#123; for (int j = i + 1; j &lt;= n; j++) &#123; int lo = 0, hi = sz(tmp) - 1; int bans = -1; while (lo &lt;= hi) &#123; int mid = (lo + hi) / 2; auto [x, y] = tmp[mid]; if (a[i] * y &gt; a[j] * x) &#123; lo = mid + 1; bans = mid; &#125; else &#123; hi = mid - 1; &#125; &#125; ans += (bans + 1) * fenmu % MOD; if (ans &gt; MOD) &#123; ans -= MOD; &#125; &#125; &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2224/problem/C 单独去修改a或者b，可能会破坏另外一个字符串的平衡，我们分情况讨论，a[i] == b[i]的时候，交换没有意义，不用管，a[i]!=b[i]的时候，我们希望两者的balance尽可能地平衡 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifbool check(const string &amp;s) &#123; int n = sz(s); int b = 0; for (int i = 0; i &lt; n; i++) &#123; b += (s[i] == &#x27;(&#x27;); b -= (s[i] == &#x27;)&#x27;); if (b &lt; 0) &#123; return false; &#125; &#125; return (b == 0);&#125;void solve() &#123; int n; cin &gt;&gt; n; string a, b; cin &gt;&gt; a &gt;&gt; b; int ba = 0, bb = 0; for (int i = 0; i &lt; n; i++) &#123; if (a[i] == b[i]) &#123; ba += (a[i] == &#x27;(&#x27;); ba -= (a[i] == &#x27;)&#x27;); bb += (b[i] == &#x27;(&#x27;); bb -= (b[i] == &#x27;)&#x27;); &#125; else &#123; if (ba &lt; bb) &#123; if (a[i] == &#x27;)&#x27;) &#123; swap(a[i], b[i]); &#125; &#125; else &#123; if (a[i] == &#x27;(&#x27;) &#123; swap(a[i], b[i]); &#125; &#125; ba += (a[i] == &#x27;(&#x27;); ba -= (a[i] == &#x27;)&#x27;); bb += (b[i] == &#x27;(&#x27;); bb -= (b[i] == &#x27;)&#x27;); &#125; &#125; if (check(a) &amp;&amp; check(b)) &#123; cout &lt;&lt; &quot;YES
&quot;; &#125; else &#123; cout &lt;&lt; &quot;NO
&quot;; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2227/problem/E 假如没有操作的话，答案就是 $$ \sum_{i=1}^{n}{a_i-\min(a_1,a_2,...,a_i)} $$ 发现只有改后缀最小值的位置才有贡献 我们记录后缀最小值出现的位置，后缀最小值相同的地方形成一个块，修改一个块的最右端，产生的贡献是块长-1，所以我们选择最大的块长-1 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve()&#123; int n; cin&gt;&gt;n; vt&lt;int&gt; a(n+5); for(int i=1;i&lt;=n;i++) cin&gt;&gt;a[i]; int mn=1e9; vt&lt;int&gt; v; ll ans=0; for(int i=n;i&gt;=1;i--) &#123; if(a[i]&lt;mn) v.push_back(i); mn=min(mn,a[i]); ans+=a[i]-mn; &#125; v.push_back(0); int mx=0; for(int i=0;i+1&lt;sz(v);i++) &#123; mx=max(mx,v[i]-v[i+1]-1); &#125; cout&lt;&lt;ans+mx&lt;&lt;&quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin&gt;&gt;tt; while(tt--) solve(); return 0;&#125; https://codeforces.com/contest/2226/problem/C 从大到小去处理就可以，但是完全不会证明 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve()&#123; int n; cin&gt;&gt;n; vt&lt;int&gt; a(n+5); for(int i=1;i&lt;=n;i++) &#123; cin&gt;&gt;a[i]; &#125; int lo=0,hi=n; auto check=[&amp;](int mid)-&gt;bool &#123; multiset&lt;int&gt; ms; for(int i=1;i&lt;=n;i++) &#123; ms.insert(a[i]); &#125; int mex=mid-1; while(mex&gt;=0) &#123; if(ms.count(mex)) &#123; auto it=ms.find(mex); ms.erase(it); mex--; continue; &#125; auto it=ms.upper_bound(2*mex); if(it!=ms.end()) &#123; ms.erase(it); mex--; continue; &#125; return false; &#125; return true; &#125;; int ans=0; while(lo&lt;=hi) &#123; int mid=(lo+hi)/2; if(check(mid)) &#123; lo=mid+1; ans=mid; &#125; else hi=mid-1; &#125; cout&lt;&lt;ans&lt;&lt;&quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin&gt;&gt;tt; while(tt--) solve(); return 0;&#125; https://ac.nowcoder.com/acm/contest/133523/C 贪心去匹配就好，证明不好证，但是去想的话，发现确实只能这么干了 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define sz(x) int((x).size())#define vt vector#define rg(x, l, r) (x).begin() + 1, (x).begin() + r + 1#define all(x) (x).begin(), (x).end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve() &#123; string s; cin &gt;&gt; s; int l = 0, r = sz(s) - 1; while (l &lt; r) &#123; if (s[l] == s[r]) &#123; l++, r--; continue; &#125; if (s[l] == &#x27;n&#x27; &amp;&amp; s[r] == &#x27;m&#x27;) &#123; if (l + 1 &lt; r &amp;&amp; s[l + 1] == &#x27;n&#x27;) &#123; l += 2; r--; continue; &#125; else &#123; cout &lt;&lt; &quot;NO
