&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/132152/C 不在正确位置的，需要都在同一个联通块，但是还可以考虑在正确位置的最大值，准确的来说是全局最大值，只要x不大于不正确的最小值和全局最大值的积，就可以，如果全局最大值是正确的位置，说明充当了一个媒介的作用 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define sz(x) int((x).size())#define vt vector#define rg(x, l, r) (x).begin() + 1, (x).begin() + r + 1#define all(x) (x).begin(), (x).end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifint main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int n, q; cin &gt;&gt; n &gt;&gt; q; vt&lt;ll&gt; a(n + 5), b(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; b[i] = a[i]; &#125; sort(rg(b, 1, n)); ll mn = 1e9; for (int i = 1; i &lt;= n; i++) &#123; if (b[i] != a[i]) &#123; mn = min(mn, a[i]); &#125; &#125; ll mn_x = mn * b[n]; while (q--) &#123; ll x; cin &gt;&gt; x; if (x &lt;= mn_x) &#123; cout &lt;&lt; &quot;Yes
&quot;; &#125; else &#123; cout &lt;&lt; &quot;No
&quot;; &#125; &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/132152/B $$ x &lt; a \ a = k \cdot x + r \ $$ 取k = 1 $$ a &gt;= x + r \ r &lt;= a - x \  ecause r &lt; x \ 	herefore r \le a - x \lt a - r \ 2r &lt; a \ r &lt;  rac{a}{2} $$ 然后所有r &lt; a / 2的值都能取到 $$ (a - r) + r = a \ r &lt; \ a - r &gt; $$ a-r为模数，r为余数，合法 其实应该先从(a-r)+r这条式子出发，这样第一个结论就显而易见了 int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; for (int i = n - 1; i &gt;= 1; i--) &#123; if (a[i] &lt; a[i + 1]) &#123; continue; &#125; int max_r = (a[i] - 1) / 2; a[i] = min(a[i + 1] - 1, max_r); &#125; for (int i = 1; i &lt; n; i++) &#123; if (a[i] &gt;= a[i + 1] || a[i] &lt;= 0) &#123; cout &lt;&lt; &quot;NO
