&quot;; return 0;&#125; https://codeforces.com/contest/2220/problem/D1 这题好难，并没有完全搞懂，核心观察点就是假设说只有2n个元素，然后每个元素都刚好出现两次，考虑S和T这两个集合 它们两个互为补集，我们会发现ask(S) == ask(T)，这时候我们应该去考虑多一个元素会发生什么情况 resa == resb的时候，说明S有0或3个特殊值下标 resa != resb的时候，说明S有1或2个特殊值下标 其他细节看代码吧，不讲了 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifint n;int ask(const vt&lt;int&gt; &amp;a) &#123; cout &lt;&lt; &quot;? &quot; &lt;&lt; sz(a) &lt;&lt; &quot; &quot;; for (int x : a) &#123; cout &lt;&lt; x &lt;&lt; &quot; &quot;; &#125; cout &lt;&lt; endl; int res; cin &gt;&gt; res; return res;&#125;vt&lt;int&gt; construct(int l, int r, int p1 = 0, int p2 = 0) &#123; vt&lt;int&gt; res; for (int i = l; i &lt;= r; i++) &#123; if (i == p1 || i == p2) &#123; continue; &#125; res.push_back(i); &#125; return res;&#125;vt&lt;int&gt; complement(const vt&lt;int&gt; &amp;a) &#123; vt&lt;int&gt; res; int pa = 0; int now = 1; while (now &lt;= 2 * n + 1) &#123; if (pa &lt; sz(a) &amp;&amp; a[pa] == now) &#123; now++; pa++; continue; &#125; res.push_back(now++); &#125; return res;&#125;void solve() &#123; cin &gt;&gt; n; int p1 = 0, p2 = 0, p3 = 0; for (int _ = 0; _ &lt; 3; _++) &#123; int lo = 1, hi = 2 * n + 1; while (lo &lt; hi) &#123; int mid = (lo + hi) / 2; auto a = construct(lo, mid, p1, p2); if (sz(a) == 0) &#123; lo = mid + 1; continue; &#125; auto b = complement(a); int resa = ask(a); int resb = ask(b); if (resa == resb) &#123; if ((sz(a) - resa) % 2) &#123; hi = mid; &#125; else &#123; lo = mid + 1; &#125; &#125; else &#123; hi = mid; &#125; &#125; if (_ == 0) &#123; p1 = lo; &#125; if (_ == 1) &#123; p2 = lo; &#125; if (_ == 2) &#123; p3 = lo; &#125; &#125; cout &lt;&lt; &quot;! &quot; &lt;&lt; p1 &lt;&lt; &quot; &quot; &lt;&lt; p2 &lt;&lt; &quot; &quot; &lt;&lt; p3 &lt;&lt; endl;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/131416/E 这题想出来了，但是方法比较新，记录一下 这里的dp[x][y]不是数量分别为x和y，而是至少为x和y #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve() &#123; int n, k; cin &gt;&gt; n &gt;&gt; k; int x, y; cin &gt;&gt; x &gt;&gt; y; vt&lt;int&gt; a(n + 5), b(n + 5); vt&lt;ll&gt; c(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i] &gt;&gt; b[i] &gt;&gt; c[i]; &#125; vt&lt;vt&lt;ll&gt;&gt; dp(x + 1, vt&lt;ll&gt;(y + 1, 1e18)); dp[0][0] = 0; for (int i = 1; i &lt;= k; i++) &#123; auto ndp = dp; for (int j1 = 0; j1 &lt;= x; j1++) &#123; for (int j2 = 0; j2 &lt;= y; j2++) &#123; ndp[j1][j2] = min(ndp[j1][j2], dp[(j1 - a[i] &gt;= 0 ? j1 - a[i] : 0)][(j2 - b[i] &gt;= 0 ? j2 - b[i] : 0)] + c[i]); &#125; &#125; dp = ndp; &#125; for (int i = k + 1; i &lt;= n; i++) &#123; auto ndp = dp; for (int j1 = 0; j1 &lt;= x; j1++) &#123; for (int j2 = 0; j2 &lt;= y; j2++) &#123; ndp[j1][j2] = min(ndp[j1][j2], ndp[(j1 - a[i] &gt;= 0 ? j1 - a[i] : 0)][(j2 - b[i] &gt;= 0 ? j2 - b[i] : 0)] + c[i]); &#125; &#125; dp = ndp; &#125; if (dp[x][y] &gt;= (ll)1e18) &#123; cout &lt;&lt; &quot;-1
&quot;; &#125; else &#123; cout &lt;&lt; dp[x][y] &lt;&lt; &quot;
&quot;; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/131539/F 这题没有学过环染色问题是不可能会的（除非是天才） 附带一个环染色问题的推导https://zhuanlan.zhihu.com/p/507310484 我直接把公式写出来吧，n种颜色，染m个格子的圆环(m &gt;= 2)的方案数就是 am = (n − 1)m + (−1)m ⋅ (n − 1) 所以这道题就是找出每个环，求每个环的方案数，其他不在环上的点的选择就是25 这个题目的图不一定是基环树，这种n条边形成的图，叫做函数图，它不一定联通，所以可能有多个环 求无向图的环方法，就简单的就是用拓扑排序 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifconst ll MOD = 998244353;ll power(ll u, ll v) &#123; ll res = 1; while (v) &#123; if (v % 2) res = res * u % MOD; u = u * u % MOD; v /= 2; &#125; return res;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5), deg(n + 5); vt&lt;vt&lt;int&gt;&gt; adj(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; adj[i].pb(a[i]); adj[a[i]].pb(i); deg[i]++; deg[a[i]]++; &#125; queue&lt;int&gt; q; for (int i = 1; i &lt;= n; i++) &#123; if (deg[i] == 1) &#123; q.push(i); &#125; &#125; while (!q.empty()) &#123; int u = q.front(); q.pop(); for (int v : adj[u]) &#123; if (--deg[v] == 1) &#123; q.push(v); &#125; &#125; &#125; int cnt = 0; for (int i = 1; i &lt;= n; i++) &#123; if (deg[i] == 2) &#123; cnt++; &#125; &#125; // db(cnt), el auto calc = [&amp;](ll m) -&gt; ll &#123; ll res = power(25, m) + (m % 2 ? -25 : 25); if (res &gt;= MOD) res -= MOD; if (res &lt; 0) res += MOD; return res; &#125;; ll ans = power(25, n - cnt); vt&lt;bool&gt; vis(n + 5); for (int i = 1; i &lt;= n; i++) &#123; if (deg[i] != 2 || vis[i]) &#123; continue; &#125; int u = i; int len = 0; int pre = 0; while (u != pre) &#123; len++; pre = u; vis[u] = true; for (int v : adj[u]) &#123; if (deg[v] != 2 || vis[v]) &#123; continue; &#125; u = v; break; &#125; &#125; ans *= calc(len); ans %= MOD; &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt = 1; // cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2217/problem/C 这道题，我不会证明，如果要证明的话，应该是挺麻烦的，之前已经证明过gcd(p, n) = 1才能用步长p走完n的剩余系，所以gcd(n, a) = 1和gcd(m, b) = 1是必要条件，然后要走回原点的话就是往下往右各走lcm(n, m)步，观察到n * m = gcd(n, m) * lcm(n, m)，往下往右总和访问了2lcm(n, m)个格子，所以如果gcd(n, m) &gt; 2的话肯定是NO，至于gcd(n, m) &lt;= 2证明如下
#include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve() &#123; ll n, m, a, b; cin &gt;&gt; n &gt;&gt; m &gt;&gt; a &gt;&gt; b; if (gcd(n, a) == 1 &amp;&amp; gcd(m, b) == 1 &amp;&amp; gcd(n, m) &lt;= 2) &#123; cout &lt;&lt; &quot;YES
&quot;; &#125; else &#123; cout &lt;&lt; &quot;NO
&quot;; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2143/problem/C 这道题，我想到了大概的做法，但是不够完善，最后还是看了题解，重点就是dp状态的设置 dp[i][j][k]表示前i个元素，然后序列当中最长子序列的个数不超过2的方案总数，j和k分别记录最长子序列的第一个和第二个数，但不完全是，为了能够记录子序列，j和k应该尽可能的大，这样在加入a[i]的时候才能判断是否产生了新的递减子序列 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifconst ll MOD = 1e9 + 7;void add(ll &amp;u, ll v) &#123; u += v; if (u &gt;= MOD) u -= MOD; if (u &lt; 0) u += MOD;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; vt&lt;vt&lt;vt&lt;ll&gt;&gt;&gt; dp(n + 5, vt&lt;vt&lt;ll&gt;&gt;(n + 5, vt&lt;ll&gt;(n + 5))); dp[0][0][0] = 1; for (int i = 1; i &lt;= n; i++) &#123; for (int j = 0; j &lt;= n; j++) &#123; for (int k = 0; k &lt;= j; k++) &#123; add(dp[i][j][k], dp[i - 1][j][k]); if (a[i] &gt;= j) &#123; add(dp[i][a[i]][k], dp[i - 1][j][k]); &#125; else if (j &gt; a[i] &amp;&amp; a[i] &gt;= k) &#123; add(dp[i][j][a[i]], dp[i - 1][j][k]); &#125; &#125; &#125; &#125; ll ans = 0; for (int j = 0; j &lt;= n; j++) &#123; for (int k = 0; k &lt;= j; k++) &#123; add(ans, dp[n][j][k]); &#125; &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2147/problem/C 这题我以为是简单的找规律思维题，结果做了超级久，看了题解也不知道在说什么，后面知道dp也能做的时候，我稍微有了点思路，但是还是蛮多坑的，首先关键的一点就是如果有两个或以上的1，那么这堆1的左右两边可以看做独立的子问题，因为它们相互不影响，然后对这些独立的子问题进行dp，dp的坑点就在于这些子问题之间也不是完全的一样，有些0出现在最开头或者最结尾，我们是需要特判的 然后dp状态也非常地奇怪，虽然转移方程是一样的，但是初值不同，看上去就好像很蠢的样子 不过也确实，这种2选1，并且依赖于前一项的选择的问题，我怎么会想不到dp呢 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve(int id) &#123; int n; cin &gt;&gt; n; string s; cin &gt;&gt; s; // if (id == 104) &#123; // cout &lt;&lt; s &lt;&lt; &quot;
