] &gt; b[i]) &#123; c[i] = a[i]; // 肯定成立的，因为这等价于没有修改 &#125; &#125; vt&lt;ll&gt; dp(L, -1e18); for (int j = 0; j &lt; sz(primes); j++) &#123; ll p = primes[j]; if (p * c[1] == a[1]) &#123; dp[j] = 0; &#125; else if (p * c[1] &lt;= b[1]) &#123; dp[j] = 1; &#125; &#125; // cerr &lt;&lt; &quot;i = 1&quot; &lt;&lt; endl; // for (int j = 0; j &lt; L; j++) &#123; // db(primes[j]), db(dp[j]), el; // &#125; for (int i = 2; i &lt;= n; i++) &#123; auto ndp = vt&lt;ll&gt;(L, -1e18); for (int j1 = 0; j1 &lt; sz(primes); j1++) &#123; ll p1 = primes[j1]; ll x1 = c[i] * p1; if (x1 == a[i]) &#123; for (int j2 = 0; j2 &lt; sz(primes); j2++) &#123; ll p2 = primes[j2]; ll x2 = c[i - 1] * p2; if (gcd(x2, a[i]) == gcd(a[i - 1], a[i])) &#123; ndp[j1] = max(ndp[j1], dp[j2]); &#125; &#125; continue; &#125; if (x1 &gt; b[i]) &#123; continue; &#125; for (int j2 = 0; j2 &lt; sz(primes); j2++) &#123; ll p2 = primes[j2]; ll x2 = c[i - 1] * p2; if (gcd(x1, x2) == gcd(a[i - 1], a[i])) &#123; ndp[j1] = max(ndp[j1], dp[j2] + 1); &#125; &#125; &#125; dp = ndp; // db(i), el; // for (int j = 0; j &lt; L; j++) &#123; // db(primes[j]), db(dp[j]), el; // &#125; &#125; cout &lt;&lt; *max_element(all(dp)) &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/130843/F 这道题涉及到搬运问题，假设有几堆果子，表示为数组a，我每次操作只能移动一个果子到另外一个堆，我要求目标状态为数组b，求最小操作次数，这就是一个搬运问题 其实这就是一个贪心问题，我们只看第一个堆，a[1]要变成b[1]，d1=a[1]-b[1]，直接a[1]=b[1],然后a[2]=a[2]+d1就好 a[2]同理，d2=a[2]-b[2],a[3]=a[3]+d2,d3=a[3]-b[3],a[4]=a4+d3,d4=a[4]-b[4] 我们代入每个d看一下，d就是每次的代价 d4=a[4]-b[4]=a4+d3-b[4]=a[4]+a[3]+d2-b[3]-b[4]=a[4]+a[3]+a[2]+d1-b[2]-b[3]-b[4]=a[4]+a[3]+a[2]+a[1]-b[1]-b[2]-b[3]-b[4] 可以看出来每个d就是a的前缀和减b的前缀和 总代价就是 $$ \sum_{i=1}^{n-1}{d_i} = \sum_{i=1}^{n-1}{prefA_i-prefB_i} $$ 然后就可以开始dp了，dp[i][s][k]表示前i项，目标总和为s,第i个数为k的最小代价 转移方程 $$ dp[i][s][k]=\mathop{min}\limits_{0\le k2 \le k} {\{dp[i-1][s-k*k][k2]\}}+cost\ cost=\left|prefA[i-1]-(s-k*k)ight| $$ 这个k2枚举会超时，我们搞个预处理个前缀最小值就好了 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve() &#123; int n; cin &gt;&gt; n; vt&lt;ll&gt; a(n + 5), pref(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; pref[i] = pref[i - 1] + a[i]; &#125; vt&lt;vt&lt;ll&gt;&gt; dp(10005, vt&lt;ll&gt;(105, 1e18)); dp[0][0] = 0; for (int i = 1; i &lt;= n; i++) &#123; // 第i个状态不应该继承i-1的状态 vt&lt;vt&lt;ll&gt;&gt; ndp = vt&lt;vt&lt;ll&gt;&gt;(10005, vt&lt;ll&gt;(105, 1e18)); vt&lt;vt&lt;ll&gt;&gt; pref_min(pref[n] + 5, vt&lt;ll&gt;(105, 1e18)); for (int j = 0; j &lt;= pref[n]; j++) &#123; for (int k = 0; k &lt;= 100; k++) &#123; if (k == 0) &#123; pref_min[j][k] = dp[j][k]; &#125; else &#123; pref_min[j][k] = min(pref_min[j][k - 1], dp[j][k]); &#125; &#125; &#125; for (int j = 0; j &lt;= pref[n]; j++) &#123; for (int k = 0; j - k * k &gt;= 0 &amp;&amp; k &lt;= 100; k++) &#123; ll cost = llabs(pref[i - 1] - (j - k * k)); ndp[j][k] = min(ndp[j][k], pref_min[j - k * k][k] + cost); &#125; &#125; dp = ndp; &#125; ll ans = 1e18; for (int k = 0; k &lt;= 100; k++) &#123; ans = min(ans, dp[pref[n]][k]); &#125; if (ans == (ll)1e18) &#123; cout &lt;&lt; &quot;-1
&quot;; &#125; else &#123; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://atcoder.jp/contests/abc450/tasks/abc450_d 思路：可以发现差值应该是和余数有关的，然后就可以考虑把每个元素%k，然后排序，每次更改的时候要么是更改最大的或者最小的，%k之后所有数的差值不超过k-1，所以一个数加上k，必然是最大的，然后呢，一旦我选择了更改最小值，那么我之后都是选择更改最小值，因为最小值已经变成最大值，我更改最大值就只是撤销操作而已，那么需不需要一开始更改最大值呢，答案是不需要因为一个元素-k，等于其他剩余元素都+k，所以更改最小值已经包含了更改最大值的情况 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifint main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); ll n, k; cin &gt;&gt; n &gt;&gt; k; vt&lt;ll&gt; a(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; a[i] %= k; &#125; sort(rg(a, 1, n)); deque&lt;ll&gt; q; for (int i = 1; i &lt;= n; i++) &#123; q.push_back(a[i]); &#125; ll ans = a[n] - a[1]; for (int i = 1; i &lt; n; i++) &#123; ll x = q.front(); q.pop_front(); x += k; q.push_back(x); ans = min(ans, q.back() - q.front()); &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;; return 0;&#125; https://ac.nowcoder.com/acm/contest/130843/E 听说这是经典题，区间dp能做，但是时间复杂度是n^4，改成线性dp又能做了，思路就是如果第i个格子被染色了，则一定存在一个操作区间右端点是i，那么我们只需要枚举右端点，然后剩下的就是在[l - 1, i - 1]这个区间里面选最小的dp #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifvoid solve() &#123; int n; cin &gt;&gt; n; vt&lt;int&gt; a(n + 5), pref(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; pref[i] = pref[i - 1] ^ a[i]; &#125; vt&lt;ll&gt; dp(n + 5, 1e18); dp[0] = 0; for (int i = 1; i &lt;= n; i++) &#123; ll mn = 1e18; for (int l = i; l &gt;= 1; l--) &#123; mn = min(mn, dp[l - 1]); dp[i] = min(dp[i], mn + (pref[i] ^ pref[l - 1])); &#125; &#125; cout &lt;&lt; dp[n] &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://ac.nowcoder.com/acm/contest/130843/E 会发现m和M都应该出现在区间端点的位置，也就是m = a[l], M = a[r]或者m = a[r], M = a[l]，然后写成f(r) + f(l)的形式就行了 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endif/*M - m - r + l(M - m) - (r - l)m = a[l], M = a[r]a[r] - a[l] - r + la[r] - r - (a[l] - l)M = a[l], m = a[r]a[l] - a[r] - r + l(a[l] + l) - (a[r] + r)*/void solve() &#123; int n; cin &gt;&gt; n; int ans = 0; int mn = 1e9, mx = -1e9; for (int i = 1; i &lt;= n; i++) &#123; int a; cin &gt;&gt; a; int t1 = a + i; int t2 = a - i; mn = min(mn, t2); mx = max(mx, t1); ans = max(&#123;ans, mx - t1, t2 - mn&#125;); &#125; cout &lt;&lt; ans &lt;&lt; &quot;
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int T; cin &gt;&gt; T; while (T--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2211/problem/B sb吧这题面，什么子序列，明明是连续子序列，害我想半天，考虑一个前缀和数组，我们会发现这个数组的增量绝对值不超过1，可以看做是离散意义上的连续，假设x&gt;y, pref[n]=x-y，易得我们只需要考虑x-y的某个约数d，总和为d的连续子数组必定存在，因为介值定理，然后2d也存在，以此类推，每个数组总和为d的划分必然存在一组，所以这道题的下界就是x-y的约数个数，然后就可以猜了，顺序数组是方案最少的，因为是递增的，所以d值存在一个，以此类推2d，3d。。。也只存在一个。x=y的话，pref[i]=0的i有两个，pref[0]和pref[n]，其实就是整个数组，所以答案是1 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#else#define db(x) 114514#define el 1919810#endifvoid solve() &#123; int x, y; cin &gt;&gt; x &gt;&gt; y; int d = abs(x - y); if (d == 0) &#123; cout &lt;&lt; &quot;1
