&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2211/problem/C2 这题根本就难到飞起，怎么可能有3000+人过的，说一下思路，我们考虑[l, r]到[l+1, r+1]之间发生的变化 我们假设a[l, r]的元素集合为A，b[l, r]元素集合为B 根据题目要求，我们要A=B 好，我们就假设A=B 变化到[l+1, r+1]的时候 A = A - {a[l]} + {a[r+1]} B = B - {b[l]} + {b[r+1]} 考虑两种两种情况
a[l] = a[r+1]
要使得A=B，那么b[l] = b[r+1]
a[l] != a[r+1]
那么a[l] = b[l], a[r+1] = b[r+1] l和r+1相差k，我们按照同余的坐标分类 如果同一个同余类里面有两个a[i]不同，那么这个同余类的所有b[i]和a[i]是相等的 否则，这个同余类只需要满足所有b[i]是相等的 做完这个过程我们需要判断[1, k]这个区间是否满足条件，过程我们已经确定没有问题了，只要初始条件没有问题，答案就没有问题，[1, k]每个坐标都属于不同的同余类，我们可以自由分配值 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifvoid solve() &#123; int n, k; cin &gt;&gt; n &gt;&gt; k; vt&lt;int&gt; a(n + 5), b(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; a[i]; &#125; for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; b[i]; &#125; for (int i = 1; i &lt;= k; i++) &#123; bool all_same = true; for (int j = i; j &lt;= n; j += k) &#123; if (a[j] != a[i]) &#123; all_same = false; &#125; &#125; if (!all_same) &#123; for (int j = i; j &lt;= n; j += k) &#123; if (b[j] != -1 &amp;&amp; b[j] != a[j]) &#123; cout &lt;&lt; &quot;NO
&quot;; return; &#125; b[j] = a[j]; &#125; &#125; else &#123; int val = -1; for (int j = i; j &lt;= n; j += k) &#123; if (b[j] != -1) &#123; val = b[j]; break; &#125; &#125; for (int j = i; j &lt;= n; j += k) &#123; if (b[j] != -1 &amp;&amp; b[j] != val) &#123; cout &lt;&lt; &quot;NO
&quot;; return; &#125; b[j] = val; &#125; &#125; &#125; // for (int i = 1; i &lt;= n; i++) &#123; // cout &lt;&lt; b[i] &lt;&lt; &quot; 
&quot;[i == n]; // &#125; vt&lt;int&gt; cnta(n + 5); for (int i = 1; i &lt;= k; i++) &#123; cnta[a[i]]++; &#125; vt&lt;int&gt; cntb(n + 5); for (int i = 1; i &lt;= k; i++) &#123; if (b[i] != -1 &amp;&amp; i &lt;= k) &#123; cntb[b[i]]++; &#125; &#125; for (int i = 1; i &lt;= k; i++) &#123; if (b[i] != -1 &amp;&amp; cntb[b[i]] &gt; cnta[b[i]]) &#123; cout &lt;&lt; &quot;NO
&quot;; return; &#125; &#125; cout &lt;&lt; &quot;YES
&quot;;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125; https://codeforces.com/contest/2211/problem/D 这题确实比C2简单，但是还是很难，首先我们考虑b[i]是怎么确定的 $$ b_i = \sum_{j=0}^{30} { inom{cnt_j}{i} \cdot 2^{j}} $$ 可以看到b[i]的值只和cnt[j]有关系，和这些1在哪个a[i]是没有关系的，我们只需要知道每个cnt[j]的值就能够构造出一个a 观察b[n]，发现只有cnt[j]==n时才有贡献，通过检查b[n]的二进制位我们就可以知道某些cnt[j]的值，然后减去这个cnt[j]对b[n-1]的贡献，然后就可以通过同样的方法知道cnt[j]==n-1的那些j，因为我们遍历了n~1的所有值，所以我们肯定能够知道所有cnt[j]的值 另外还有一点，在减去贡献的时候我们可能会想说b[i]已经取过模了，我们还能够判断它的二进制位吗，当我们减去其他cnt[j] &gt; i的贡献的时候，剩下能产生贡献的必然是cnt[j] == i的，而它们最大的贡献就是C(i, i) * 2 ^ j，不会超过MOD，所以是等价于没有取模过的 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;#define vt vector#define pb push_back#define sz(x) int(x.size())#define rg(x, l, r) x.begin() + l, x.begin() + r + 1#define all(x) x.begin(), x.end()#ifdef LOCAL#define db(x) cerr &lt;&lt; #x &lt;&lt; &quot; = &quot; &lt;&lt; (x) &lt;&lt; &quot; &quot;#define el cerr &lt;&lt; endl#define ts cerr &lt;&lt; &quot;line: &quot; &lt;&lt; __LINE__ &lt;&lt; endl#else#define db(x) 114514#define el 1919810#define ts 42#endifconst ll MOD = 1e9 + 7;vector&lt;ll&gt; fac, inv_fac;ll power(ll u, ll v) &#123; ll res = 1; while (v) &#123; if (v % 2) res = res * u % MOD; u = u * u % MOD; v /= 2; &#125; return res;&#125;void combInit(int n) &#123; fac.resize(n + 1); inv_fac.resize(n + 1); fac[0] = 1; for (int i = 1; i &lt;= n; i++) &#123; fac[i] = fac[i - 1] * i % MOD; &#125; inv_fac[n] = power(fac[n], MOD - 2); for (int i = n - 1; i &gt;= 0; i--) &#123; inv_fac[i] = inv_fac[i + 1] * (i + 1) % MOD; &#125;&#125;ll C(int n, int k) &#123; if (n &lt; k) &#123; return 0; &#125; return (fac[n] * inv_fac[k] % MOD) * inv_fac[n - k] % MOD;&#125;void solve() &#123; int n; cin &gt;&gt; n; vt&lt;ll&gt; b(n + 5); for (int i = 1; i &lt;= n; i++) &#123; cin &gt;&gt; b[i]; &#125; vt&lt;int&gt; cnt(30); for (int i = n; i &gt;= 1; i--) &#123; for (int j = 0; j &lt; 30; j++) &#123; if (cnt[j] &gt; i) &#123; b[i] -= C(cnt[j], i) * power(2, j) % MOD; if (b[i] &lt; 0) &#123; b[i] += MOD; &#125; &#125; &#125; for (int j = 0; j &lt; 30; j++) &#123; if (b[i] &gt;&gt; j &amp; 1) &#123; cnt[j] = i; &#125; &#125; &#125; vt&lt;int&gt; a(n + 5); for (int j = 0; j &lt; 30; j++) &#123; for (int i = 1; i &lt;= cnt[j]; i++) &#123; a[i] += 1 &lt;&lt; j; &#125; &#125; for (int i = 1; i &lt;= n; i++) &#123; cout &lt;&lt; a[i] &lt;&lt; &quot; 
&quot;[i == n]; &#125;&#125;int main() &#123; ios::sync_with_stdio(false); cin.tie(nullptr); combInit(1e5); int tt; cin &gt;&gt; tt; while (tt--) &#123; solve(); &#125; return 0;&#125;
